import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) tafsīr: similar verses (al-mutashābih al-lafẓī), maqāṣid, methodology and sources of tafsīr, the schools of the Companions and Successors, reports on named verses and the classical commentaries. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "xtf-001", s: "tafsir", g: 4, d: 7, t: ["mutashabih-lafzi", "similar-verses"], src: "al-Karmānī, al-Burhān fī Mutashābih al-Qurʾān; al-Zamakhsharī, al-Kashshāf, on 6:151 and 17:31; Ibn Kathīr, Tafsīr", v: "6:151", w: 20,
    en: ["The verse shown promises provision first to the parents and then to the children, while a similar verse in al-Isrāʾ (17:31) reverses the order. What is the classical explanation?", ["Here the fear is of present poverty, so the parents are mentioned first as the ones in need; in al-Isrāʾ the fear is of future poverty, so the children, whose provision is a concern, come first", "The two verses were revealed to different people", "The order has no significance and is a matter of rhyme alone", "One verse is abrogated by the other"], "In al-Anʿām the phrase is ‘because of poverty’ (min imlāq), referring to a poverty already existing in the parents, so God promises to provide for the parents first. In al-Isrāʾ it is ‘for fear of poverty’ (khashya), a fear of future need, so the children, whom the parents fear to feed, are named first. Al-Karmānī and others give this as a model of how a change in order follows the context."],
    de: ["Der gezeigte Vers verheißt zuerst den Eltern und dann den Kindern Versorgung, während ein ähnlicher Vers in al-Isrāʾ (17:31) die Reihenfolge umkehrt. Wie lautet die klassische Erklärung?", ["Hier geht es um die Furcht vor gegenwärtiger Armut, daher werden zuerst die Eltern als die Bedürftigen genannt; in al-Isrāʾ geht es um die Furcht vor künftiger Armut, daher stehen die Kinder, um deren Versorgung man sich sorgt, an erster Stelle", "Die beiden Verse wurden an verschiedene Menschen gerichtet", "Die Reihenfolge hat keine Bedeutung und ist allein eine Frage des Reims", "Ein Vers ist durch den anderen aufgehoben"], "In al-Anʿām heißt es ‚wegen Armut‘ (min imlāq), was auf eine schon bestehende Armut der Eltern verweist; daher verheißt Gott zuerst den Eltern Versorgung. In al-Isrāʾ heißt es ‚aus Furcht vor Armut‘ (ḫašya), der Furcht vor künftiger Not; daher werden die Kinder, die zu ernähren die Eltern fürchten, zuerst genannt. Al-Karmānī und andere geben dies als Muster dafür, wie ein Wechsel der Reihenfolge dem Kontext folgt."],
    ar: ["الآية المعروضة تعد بالرزق الوالدين أولًا ثم الأولاد، بينما تعكس آية مشابهة في الإسراء (31) الترتيب. ما التعليل الكلاسيكي؟", ["هنا الخوف من فقر قائم فقُدّم الوالدان لحاجتهما، وفي الإسراء الخوف من فقر متوقع فقُدّم الأولاد الذين يُخشى إطعامهم", "نزلت الآيتان في أناس مختلفين", "لا دلالة للترتيب وهو للفاصلة وحدها", "إحدى الآيتين منسوخة بالأخرى"], "في الأنعام عبّر النص بالإملاق وهو فقر موجود لدى الوالدين فبدأ بالوعد بحاجتهم، وفي الإسراء عبّر بخشية الإملاق وهي خشية فقر مستقبل فبدأ بالأولاد الذين يُخشى إطعامهم، ويذكر الكرماني وغيره ذلك مثالًا على أن اختلاف الترتيب يتبع السياق."] },

  { id: "xtf-002", s: "tafsir", g: 4, d: 7, t: ["mutashabih-lafzi", "similar-verses"], src: "al-Zamakhsharī, al-Kashshāf, on 2:49 and 14:6; al-Karmānī, al-Burhān fī Mutashābih al-Qurʾān; al-Iskāfī, Durrat al-Tanzīl", v: "2:49", w: 9,
    en: ["The highlighted verb in this verse has no conjunction before it, whereas in 14:6 the corresponding verb has wāw. How is the difference explained?", ["Here the slaying is an explanation of the ‘evil of the punishment’, so no wāw; in 14:6 the slaying is mentioned as a separate kind of torment alongside others, so it is joined by wāw", "The wāw was dropped by a scribal slip", "The verses refer to two different Pharaohs", "The difference is only because of the recitation"], "Al-Zamakhsharī explains that without the wāw the clause is an explanation of the suffering (the slaying of sons is the very worst of ‘evil punishment’), while with the wāw in 14:6 the slaying is added as another distinct torment, since the speech there reminds of blessings and lists the types of torment. Al-Karmānī and al-Iskāfī give similar accounts."],
    de: ["Das markierte Verb in diesem Vers hat keine Konjunktion davor, während in 14:6 das entsprechende Verb ein Wāw hat. Wie wird der Unterschied erklärt?", ["Hier ist das Abschlachten eine Erläuterung der ‚schlimmen Qual‘, daher kein Wāw; in 14:6 wird das Abschlachten als eigene Art der Pein neben anderen genannt und daher mit Wāw angeschlossen", "Das Wāw fiel durch ein Schreibversehen aus", "Die Verse beziehen sich auf zwei verschiedene Pharaonen", "Der Unterschied beruht nur auf der Rezitation"], "Az-Zamaḫšarī erklärt, ohne Wāw sei der Satz eine Erläuterung des Leidens (das Abschlachten der Söhne ist das schlimmste Stück der ‚schlimmen Qual‘), mit Wāw in 14:6 sei das Abschlachten als weitere, eigene Pein hinzugefügt, da die Rede dort an Wohltaten erinnert und die Arten der Pein aufzählt. Al-Karmānī und al-Iskāfī geben ähnliche Darstellungen."],
    ar: ["الفعل المظلل في هذه الآية بلا حرف عطف قبله بينما اقترن الفعل المقابل بالواو في إبراهيم 6. كيف يفسَّر الفرق؟", ["هنا التذبيح بيان لسوء العذاب فلا واو، وفي إبراهيم 6 هو نوع مستقل من العذاب إلى جانب غيره فعُطف بالواو", "سقطت الواو بسهو من الكاتب", "الآيتان في فرعونين مختلفين", "الفرق في القراءة فقط"], "يبيّن الزمخشري أنه بلا واو بيان للعذاب (فتذبيح الأبناء أشدّ سوء العذاب)، وبالواو في إبراهيم 6 هو عذاب آخر مضاف، لأن سياق إبراهيم تذكير بالنعم وتعداد لأنواع البلاء، وللكرماني والإسكافي كلام قريب."] },

  { id: "xtf-003", s: "tafsir", g: 4, d: 7, t: ["mutashabih-lafzi", "similar-verses"], src: "al-Karmānī, al-Burhān fī Mutashābih al-Qurʾān; Ibn al-Zubayr al-Gharnāṭī, Malāk al-Taʾwīl; Zakariyyā al-Anṣārī, Fatḥ al-Raḥmān", v: "14:34", w: 14,
    en: ["The verse shown ends with a description of the human being as very unjust and ungrateful, whereas the similar verse in al-Naḥl (16:18) ends with a name of God. How do the commentators explain the difference?", ["Each ending fits its context: in Ibrāhīm the verse stresses the human failing in the face of countless favours, and in al-Naḥl it stresses God’s mercy in forgiving the shortcoming in thanking Him", "The endings are interchangeable and were chosen by the scribes", "One of the two verses is Makkan and the other Madinan, so the endings differ", "The two endings refer to the same attribute"], "Both verses speak of the impossibility of counting God’s favours. In Ibrāhīm the preceding verses mention the unbelievers’ denial, so the ending highlights the wrong and ingratitude of the human being. In al-Naḥl the surrounding verses deal with God’s power and mercy, so the ending is ‘Forgiving, Merciful’. This is a standard example of how the closing of a verse (fāṣila) fits its context."],
    de: ["Der gezeigte Vers endet mit einer Beschreibung des Menschen als sehr ungerecht und undankbar, während der ähnliche Vers in an-Naḥl (16:18) mit einem Gottesnamen endet. Wie erklären die Kommentatoren den Unterschied?", ["Jedes Ende passt zu seinem Kontext: In Ibrāhīm betont der Vers das menschliche Versagen angesichts zahlloser Gaben, in an-Naḥl Gottes Erbarmen, das das Zurückbleiben im Dank vergibt", "Die Enden sind austauschbar und wurden von den Schreibern gewählt", "Einer der beiden Verse ist mekkanisch und der andere medinensisch, daher unterscheiden sich die Enden", "Die beiden Enden beziehen sich auf dieselbe Eigenschaft"], "Beide Verse sprechen von der Unmöglichkeit, Gottes Gaben zu zählen. In Ibrāhīm erwähnen die vorangehenden Verse die Leugnung der Ungläubigen, daher hebt das Ende das Unrecht und die Undankbarkeit des Menschen hervor. In an-Naḥl behandeln die umgebenden Verse Gottes Macht und Erbarmen, daher lautet das Ende ‚Allvergebend, Barmherzig‘. Dies ist ein Standardbeispiel dafür, wie der Versschluss (Fāṣila) zu seinem Kontext passt."],
    ar: ["تنتهي الآية المعروضة بوصف الإنسان بالظلم والكفر، بينما تنتهي الآية المشابهة في النحل 18 باسمين لله. كيف يفسّر المفسرون الفرق؟", ["لكل خاتمة سياقها: في إبراهيم يتحدث عن تقصير الإنسان أمام نعم لا تُحصى، وفي النحل عن رحمة الله التي تغفر تقصير الشكر", "الخاتمتان متبادلتان واختارهما الكتبة", "إحدى الآيتين مكية والأخرى مدنية فاختلفت الخاتمتان", "الخاتمتان تشيران إلى الصفة نفسها"], "كلتا الآيتين في عجز الإنسان عن إحصاء نعم الله، وفي سورة إبراهيم يسبق جحود الكافرين فناسب الختام بذكر ظلم الإنسان وكفره، وفي النحل يدور السياق على قدرة الله ورحمته فناسب الختام بالمغفرة والرحمة. وهي مثال معروف على مناسبة فاصلة الآية لسياقها."] },

  { id: "xtf-004", s: "tafsir", g: 4, d: 6, t: ["mutashabih-lafzi", "classical-works"], src: "al-Karmānī, al-Burhān fī Mutashābih al-Qurʾān; al-Iskāfī, Durrat al-Tanzīl wa-Ghurrat al-Taʾwīl; Ibn al-Zubayr al-Gharnāṭī, Malāk al-Taʾwīl; Zakariyyā al-Anṣārī, Fatḥ al-Raḥmān",
    en: ["Which of the following is a classical work on the similarity between Quranic verses with slightly different wording (al-mutashābih al-lafẓī)?", ["al-Burhān fī Mutashābih al-Qurʾān by al-Karmānī", "al-Muqaddima al-Jazariyya by Ibn al-Jazarī", "Asbāb al-Nuzūl by al-Wāḥidī", "al-Ashbāh wa-l-Naẓāʾir by al-Suyūṭī"], "The literature on al-mutashābih al-lafẓī includes al-Karmānī’s al-Burhān, al-Iskāfī’s Durrat al-Tanzīl, Ibn al-Zubayr’s Malāk al-Taʾwīl and Zakariyyā al-Anṣārī’s Fatḥ al-Raḥmān. The Jazariyya is on tajwīd, the Asbāb on occasions, and al-Ashbāh on grammar and jurisprudence."],
    de: ["Welches der folgenden ist ein klassisches Werk über die Ähnlichkeit zwischen Koranversen mit leicht abweichendem Wortlaut (al-mutashābih al-lafẓī)?", ["Al-Burhān fī Mutashābih al-Qurʾān von al-Karmānī", "Al-Muqaddima al-Ǧazariyya von Ibn al-Ǧazarī", "Asbāb an-Nuzūl von al-Wāḥidī", "Al-Ašbāh wa-n-Naẓāʾir von as-Suyūṭī"], "Zur Literatur über al-mutashābih al-lafẓī gehören al-Karmānīs al-Burhān, al-Iskāfīs Durrat at-Tanzīl, Ibn az-Zubairs Malāk at-Taʾwīl und Zakarīyā al-Anṣārīs Fatḥ ar-Raḥmān. Die Ǧazariyya handelt vom Tağwīd, die Asbāb von Anlässen, und al-Ašbāh von Grammatik und Rechtswissenschaft."],
    ar: ["أي مما يأتي كتاب كلاسيكي في تشابه الآيات اللفظي مع اختلاف يسير في اللفظ؟", ["البرهان في متشابه القرآن للكرماني", "المقدمة الجزرية لابن الجزري", "أسباب النزول للواحدي", "الأشباه والنظائر للسيوطي"], "من مؤلفات المتشابه اللفظي «البرهان» للكرماني و«درة التنزيل» للإسكافي و«ملاك التأويل» لابن الزبير و«فتح الرحمن» لزكريا الأنصاري، أما الجزرية ففي التجويد وأسباب النزول في الأسباب والأشباه والنظائر في النحو والفقه."] },

  { id: "xtf-005", s: "tafsir", g: 4, d: 6, t: ["maqasid", "ghazali"], tr: ["comparative"], src: "al-Ghazālī, al-Mustaṣfā min ʿIlm al-Uṣūl; al-Juwaynī, al-Burhān fī Uṣūl al-Fiqh",
    en: ["Which five necessities does al-Ghazālī say the sharīʿa aims to protect?", ["Religion, life, intellect, lineage and property", "Prayer, fasting, zakāt, Ḥajj and testimony", "Honour, family, justice, trade and knowledge", "Law, kingship, treaties, taxes and war"], "In al-Mustaṣfā, al-Ghazālī names the five as the preservation of dīn, nafs, ʿaql, nasl (offspring) and māl. He treats each as a ‘necessity’ (ḍarūra) whose protection is the basis of public interest (maṣlaḥa). Later, al-Qarāfī and others added the protection of honour (ʿirḍ) as a sixth, after earlier classification by al-Juwaynī."],
    de: ["Welche fünf Notwendigkeiten soll die Scharia nach al-Ġazālī schützen?", ["Religion, Leben, Verstand, Abstammung und Eigentum", "Gebet, Fasten, Zakāt, Ḥaǧǧ und Zeugnis", "Ehre, Familie, Gerechtigkeit, Handel und Wissen", "Recht, Königtum, Verträge, Steuern und Krieg"], "In al-Mustaṣfā nennt al-Ġazālī die fünf als Bewahrung von Dīn, Nafs, ʿAql, Nasl (Nachkommenschaft) und Māl. Er behandelt jede als ‚Notwendigkeit‘ (ḍarūra), deren Schutz die Grundlage des Gemeinwohls (maṣlaḥa) ist. Später fügten al-Qarāfī und andere den Schutz der Ehre (ʿirḍ) als sechsten hinzu, nach einer früheren Einteilung durch al-Ǧuwainī."],
    ar: ["ما الضروريات الخمس التي يقول الغزالي إن الشريعة تهدف إلى حفظها؟", ["الدين والنفس والعقل والنسل والمال", "الصلاة والصيام والزكاة والحج والشهادة", "العرض والأسرة والعدل والتجارة والعلم", "القانون والملك والمعاهدات والضرائب والحرب"], "يذكر الغزالي في «المستصفى» الخمسة: حفظ الدين والنفس والعقل والنسل والمال، ويعدّ كلًّا منها ضرورة يقوم حفظها عليها أساس المصلحة. وأضاف القرافي وغيره لاحقًا حفظ العرض سادسًا، بعد تقسيم الجويني السابق."] },

  { id: "xtf-006", s: "tafsir", g: 4, d: 6, t: ["maqasid", "shatibi"], src: "al-Shāṭibī, al-Muwāfaqāt fī Uṣūl al-Sharīʿa, kitāb al-maqāṣid",
    en: ["Into which three levels does al-Shāṭibī divide the objectives of the sharīʿa in al-Muwāfaqāt?", ["Necessities (ḍarūriyyāt), needs (ḥājiyyāt) and improvements (taḥsīniyyāt)", "Obligations, prohibitions and recommendations", "Fundamentals, branches and customs", "Individual, family and state"], "Al-Shāṭibī (d. 790 AH) ranks the interests by their urgency: ḍarūriyyāt (necessities, without which life and religion collapse), ḥājiyyāt (needs that remove hardship) and taḥsīniyyāt (refinements and fine conduct). Each level is served by the lower ones. His division became the standard framework of maqāṣid thinking."],
    de: ["In welche drei Stufen gliedert aš-Šāṭibī die Ziele der Scharia in al-Muwāfaqāt?", ["Notwendigkeiten (ḍarūriyyāt), Bedürfnisse (ḥāǧiyyāt) und Verbesserungen (taḥsīniyyāt)", "Pflichten, Verbote und Empfehlungen", "Grundlagen, Zweige und Bräuche", "Einzelner, Familie und Staat"], "Aš-Šāṭibī (gest. 790 n. H.) ordnet die Interessen nach ihrer Dringlichkeit: ḍarūriyyāt (Notwendigkeiten, ohne die Leben und Religion zusammenbrechen), ḥāǧiyyāt (Bedürfnisse, die Härte beseitigen) und taḥsīniyyāt (Verfeinerungen und gute Sitte). Jede Stufe wird von den niedrigeren gestützt. Seine Einteilung wurde zum Standardrahmen des Maqāṣid-Denkens."],
    ar: ["إلى أي ثلاث مراتب يقسم الشاطبي مقاصد الشريعة في «الموافقات»؟", ["الضروريات والحاجيات والتحسينيات", "الواجبات والمحرمات والمستحبات", "الأصول والفروع والعادات", "الفرد والأسرة والدولة"], "يرتب الشاطبي (ت 790هـ) المصالح بحسب شدة الحاجة إليها: الضروريات التي لا تقوم الحياة والدين بدونها، والحاجيات التي ترفع الحرج، والتحسينيات من مكارم الأخلاق، وتخدم المراتب الدنيا العليا. وصار تقسيمه الإطار المعتمد في فكر المقاصد."] },

  { id: "xtf-007", s: "tafsir", g: 4, d: 7, t: ["maqasid", "ibn-ashur"], src: "Ibn ʿĀshūr, al-Taḥrīr wa-l-Tanwīr, muqaddima 4 (maqāṣid al-Qurʾān)",
    en: ["In the introduction to al-Taḥrīr wa-l-Tanwīr, Ibn ʿĀshūr lists the principal purposes (maqāṣid) of the Quran. Which of these is among his eight?", ["Reforming belief, refining character, legislation, governing the community, stories of earlier nations, teaching, warnings and promises, and inimitability", "Collecting hadith, fixing the recitation, ordering the sūras, copying the muṣḥaf, counting verses, writing commentary, translating, and teaching Arabic", "Founding the schools, ordering the army, issuing coins, collecting taxes, building mosques, appointing judges, sending envoys, and ruling the lands", "Describing the stars, measuring the earth, dividing the seasons, naming the plants, describing animals, classifying minerals, medicine, and arithmetic"], "Ibn ʿĀshūr (d. 1973) identifies eight chief aims: iṣlāḥ al-iʿtiqād, tahdhīb al-akhlāq, al-tashrīʿ, siyāsat al-umma, al-qaṣaṣ wa-akhbār al-umam, al-taʿlīm, al-mawāʿiẓ wa-l-indhār wa-l-tabshīr, and al-iʿjāz. He uses them as a guide in interpretation, to avoid reading verses outside their purpose."],
    de: ["In der Einleitung zu at-Taḥrīr wa-t-Tanwīr zählt Ibn ʿĀšūr die Hauptzwecke (maqāṣid) des Korans auf. Welcher gehört zu seinen acht?", ["Reform des Glaubens, Veredelung des Charakters, Gesetzgebung, Lenkung der Gemeinschaft, Geschichten früherer Völker, Lehre, Warnungen und Verheißungen sowie Unnachahmlichkeit", "Hadithe sammeln, die Rezitation festlegen, die Suren ordnen, den Muṣḥaf kopieren, Verse zählen, Kommentar schreiben, übersetzen und Arabisch lehren", "Schulen gründen, das Heer ordnen, Münzen prägen, Steuern erheben, Moscheen bauen, Richter ernennen, Gesandte schicken und die Länder regieren", "Sterne beschreiben, die Erde vermessen, die Jahreszeiten einteilen, Pflanzen benennen, Tiere beschreiben, Mineralien einteilen, Medizin und Arithmetik"], "Ibn ʿĀšūr (gest. 1973) nennt acht Hauptziele: iṣlāḥ al-iʿtiqād, tahḏīb al-aḫlāq, at-tašrīʿ, siyāsat al-umma, al-qaṣaṣ wa-aḫbār al-umam, at-taʿlīm, al-mawāʿiẓ wa-l-inḏār wa-t-tabšīr und al-iʿǧāz. Er nutzt sie als Leitfaden der Auslegung, um zu vermeiden, Verse außerhalb ihres Zwecks zu lesen."],
    ar: ["في مقدمة «التحرير والتنوير» يعدّد ابن عاشور المقاصد الرئيسة للقرآن. أي ثمانية منها هي المذكورة؟", ["إصلاح الاعتقاد وتهذيب الأخلاق والتشريع وسياسة الأمة والقصص وأخبار الأمم والتعليم والمواعظ والإنذار والتبشير والإعجاز", "جمع الحديث وضبط القراءة وترتيب السور ونسخ المصحف وعدّ الآيات وتأليف التفسير والترجمة وتعليم العربية", "تأسيس المذاهب وتنظيم الجيش وسك النقود وجباية الضرائب وبناء المساجد وتعيين القضاة وإرسال السفراء وحكم البلاد", "وصف النجوم وقياس الأرض وتقسيم الفصول وتسمية النبات ووصف الحيوان وتصنيف المعادن والطب والحساب"], "حدد ابن عاشور (ت 1973م) ثمانية مقاصد رئيسة هي: إصلاح الاعتقاد، وتهذيب الأخلاق، والتشريع، وسياسة الأمة، والقصص وأخبار الأمم، والتعليم، والمواعظ والإنذار والتبشير، والإعجاز، ويتخذها هاديًا في التفسير لئلا تُقرأ الآيات خارج مقصدها."] },

  { id: "xtf-008", s: "tafsir", g: 4, d: 6, t: ["maqasid", "classical-works"], src: "al-ʿIzz ibn ʿAbd al-Salām, Qawāʿid al-Aḥkām fī Maṣāliḥ al-Anām; Ibn ʿĀshūr, Maqāṣid al-Sharīʿa al-Islāmiyya",
    en: ["Which classical work by al-ʿIzz ibn ʿAbd al-Salām builds the whole law on obtaining benefits and warding off harm?", ["Qawāʿid al-Aḥkām fī Maṣāliḥ al-Anām", "al-Muwāfaqāt", "al-Mustaṣfā", "Maqāṣid al-Sharīʿa al-Islāmiyya"], "Al-ʿIzz ibn ʿAbd al-Salām (d. 660 AH), the ‘Sultan of the scholars’, wrote Qawāʿid al-Aḥkām, in which rulings are explained through jalb al-maṣāliḥ and darʾ al-mafāsid. Al-Muwāfaqāt is by al-Shāṭibī, al-Mustaṣfā by al-Ghazālī, and Maqāṣid al-Sharīʿa al-Islāmiyya by Ibn ʿĀshūr."],
    de: ["Welches klassische Werk von al-ʿIzz ibn ʿAbd as-Salām gründet das gesamte Recht auf Nutzengewinn und Schadensabwehr?", ["Qawāʿid al-Aḥkām fī Maṣāliḥ al-Anām", "Al-Muwāfaqāt", "Al-Mustaṣfā", "Maqāṣid aš-Šarīʿa al-Islāmiyya"], "Al-ʿIzz ibn ʿAbd as-Salām (gest. 660 n. H.), der ‚Sultan der Gelehrten‘, schrieb Qawāʿid al-Aḥkām, in dem Urteile durch ǧalb al-maṣāliḥ und darʾ al-mafāsid erklärt werden. Al-Muwāfaqāt stammt von aš-Šāṭibī, al-Mustaṣfā von al-Ġazālī und Maqāṣid aš-Šarīʿa al-Islāmiyya von Ibn ʿĀšūr."],
    ar: ["أي كتاب كلاسيكي للعز بن عبد السلام يبني الشريعة كلها على جلب المصالح ودرء المفاسد؟", ["قواعد الأحكام في مصالح الأنام", "الموافقات", "المستصفى", "مقاصد الشريعة الإسلامية"], "ألّف العز بن عبد السلام (ت 660هـ) سلطان العلماء «قواعد الأحكام» وفيه يعلل الأحكام بجلب المصالح ودرء المفاسد، أما «الموافقات» فللشاطبي و«المستصفى» للغزالي و«مقاصد الشريعة الإسلامية» لابن عاشور."] },

  { id: "xtf-009", s: "tafsir", g: 4, d: 6, t: ["methodology", "sources-of-tafsir"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; Ibn Kathīr, Tafsīr, introduction",
    en: ["In what order does Ibn Taymiyya’s Muqaddima fī Uṣūl al-Tafsīr place the sources of the best commentary?", ["The Quran by the Quran, then the Sunna, then the statements of the Companions, then those of the Successors, and then the Arabic language", "The reader’s opinion, then poetry, then the Sunna", "The Companions, then the Sunna, then the Quran", "The language first, then the Quran, then the opinions of the Successors"], "Ibn Taymiyya says that the best way is to interpret the Quran by the Quran, because what is brief in one place is explained in another; then the Sunna, which explains the Quran; then the Companions, who witnessed the revelation; then the leading Successors; and the language as a support. Ibn Kathīr follows the same order in his introduction."],
    de: ["In welcher Reihenfolge ordnet Ibn Taimiyyas Muqaddima fī Uṣūl at-Tafsīr die Quellen des besten Kommentars?", ["Der Koran durch den Koran, dann die Sunna, dann die Aussagen der Gefährten, dann die der Nachfolger und dann die arabische Sprache", "Die Meinung des Lesers, dann Dichtung, dann die Sunna", "Die Gefährten, dann die Sunna, dann der Koran", "Zuerst die Sprache, dann der Koran, dann die Meinungen der Nachfolger"], "Ibn Taimiyya sagt, der beste Weg sei, den Koran durch den Koran auszulegen, denn was an einer Stelle knapp ist, wird an anderer erklärt; dann die Sunna, die den Koran erläutert; dann die Gefährten, die die Offenbarung miterlebten; dann die führenden Nachfolger; und die Sprache als Stütze. Ibn Kaṯīr folgt in seiner Einleitung derselben Ordnung."],
    ar: ["بأي ترتيب تضع «مقدمة في أصول التفسير» لابن تيمية مصادر أحسن التفسير؟", ["تفسير القرآن بالقرآن ثم بالسنة ثم بأقوال الصحابة ثم بأقوال التابعين ثم باللغة العربية", "رأي المفسر ثم الشعر ثم السنة", "الصحابة ثم السنة ثم القرآن", "اللغة أولًا ثم القرآن ثم آراء التابعين"], "قال ابن تيمية إن أصح الطرق تفسير القرآن بالقرآن لأن ما أُجمل في موضع فُسّر في آخر، ثم السنة لأنها شارحة للقرآن، ثم أقوال الصحابة لمشاهدتهم الوحي، ثم كبار التابعين، واللغة سند، وسار ابن كثير على الترتيب نفسه في مقدمته."] },

  { id: "xtf-010", s: "tafsir", g: 4, d: 6, t: ["methodology", "israiliyyat"], src: "Ibn Kathīr, Tafsīr, introduction (on al-isrāʾīliyyāt); Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr",
    en: ["How does Ibn Kathīr classify the reports taken from the People of the Book (isrāʾīliyyāt) for the purposes of tafsīr?", ["Three kinds: what our sources confirm as true, what they show to be false, and what is neither (to be neither believed nor denied, and used with caution)", "All are valid because they are older scripture", "All are forbidden and may never be quoted", "Two kinds only: those on law and those on stories"], "Ibn Kathīr, relying on the hadith ‘narrate from the Children of Israel, there is no harm’ and on the warning not to believe or disbelieve them, says that some reports agree with the Quran and Sunna and may be cited as support, some contradict them and are rejected, and the rest, about which the sources are silent, may be narrated for illustration but not believed as a matter of faith or used as a proof."],
    de: ["Wie ordnet Ibn Kaṯīr die Berichte der Leute des Buches (Isrāʾīliyyāt) für die Zwecke des Tafsīr ein?", ["In drei Arten: was unsere Quellen als wahr bestätigen, was sie als falsch erweisen und was keines von beiden ist (weder zu glauben noch zu leugnen, mit Vorsicht zu verwenden)", "Alle sind gültig, da sie ältere Schrift sind", "Alle sind verboten und dürfen nie zitiert werden", "Nur in zwei Arten: die über das Recht und die über Geschichten"], "Ibn Kaṯīr stützt sich auf den Hadith ‚berichtet von den Kindern Israels, es ist kein Schaden dabei‘ und auf die Warnung, sie weder zu glauben noch zu leugnen, und sagt: Manche Berichte stimmen mit Koran und Sunna überein und dürfen als Stütze angeführt werden, manche widersprechen ihnen und werden verworfen, und der Rest, zu dem die Quellen schweigen, darf zur Veranschaulichung erzählt, aber weder als Glaubenssache geglaubt noch als Beweis verwendet werden."],
    ar: ["كيف يصنّف ابن كثير الروايات المأخوذة عن أهل الكتاب (الإسرائيليات) في التفسير؟", ["ثلاثة أنواع: ما يصدقه مصدرنا، وما يكذبه، وما هو غير ذلك فلا يُصدَّق ولا يُكذَّب ويُستعمل بحذر", "كلها صحيحة لأنها كتب أقدم", "كلها ممنوعة ولا تُروى أبدًا", "نوعان فقط: ما في التشريع وما في القصص"], "اعتمد ابن كثير على الحديث الذي يأذن بالتحديث عن بني إسرائيل وعلى النهي عن تصديقهم وتكذيبهم، فقال إن منها ما يوافق القرآن والسنة فيُستشهد به، ومنها ما يخالفهما فيُرد، وما سكتت عنه المصادر يجوز روايته للاستئناس دون اعتقاده أو الاحتجاج به."] },

  { id: "xtf-011", s: "tafsir", g: 4, d: 7, t: ["methodology", "tafsir-bi-l-ray"], src: "al-Dhahabī, al-Tafsīr wa-l-Mufassirūn; al-Zarkashī, al-Burhān, naw‘ 41; al-Suyūṭī, al-Itqān, naw‘ 78",
    en: ["How do scholars reconcile the hadith that warns against explaining the Quran ‘by one’s own opinion’ with the long tradition of tafsīr bi-l-raʾy?", ["They distinguish praiseworthy raʾy (informed by language, Sunna and the sciences) from blameworthy raʾy (whim, ignorance or support for a prior doctrine)", "They hold that all tafsīr bi-l-raʾy is forbidden", "They hold that raʾy is allowed to everyone without conditions", "They say the hadith was abrogated"], "Scholars say the warning concerns speaking without knowledge or on the basis of whim or sectarian purpose. Ijtihād in tafsīr that is grounded in Arabic, the Sunna, the Companions’ statements, asbāb al-nuzūl and the sciences is praiseworthy, and the reports show that the Companions themselves explained by raʾy. The scholars set conditions for the mufassir, including the language sciences."],
    de: ["Wie gleichen Gelehrte den Hadith, der davor warnt, den Koran ‚nach eigener Meinung‘ auszulegen, mit der langen Tradition des Tafsīr bi-r-raʾy aus?", ["Sie unterscheiden lobenswertes Raʾy (gestützt auf Sprache, Sunna und die Wissenschaften) von tadelnswertem Raʾy (Laune, Unwissen oder Stützung einer vorgefassten Lehre)", "Sie halten jedes Tafsīr bi-r-raʾy für verboten", "Sie halten Raʾy ohne Bedingungen für jeden für erlaubt", "Sie sagen, der Hadith sei aufgehoben"], "Die Gelehrten sagen, die Warnung betreffe das Reden ohne Wissen oder aus Laune oder zu sektiererischen Zwecken. Iǧtihād im Tafsīr, der auf dem Arabischen, der Sunna, den Aussagen der Gefährten, den Asbāb an-nuzūl und den Wissenschaften gründet, ist lobenswert, und die Berichte zeigen, dass schon die Gefährten nach Raʾy auslegten. Die Gelehrten setzten Bedingungen für den Mufassir, darunter die Sprachwissenschaften."],
    ar: ["كيف يجمع العلماء بين الحديث المحذّر من تفسير القرآن «بالرأي» وبين تاريخ طويل من التفسير بالرأي؟", ["يفرّقون بين رأي محمود قائم على اللغة والسنة والعلوم، ورأي مذموم قائم على الهوى والجهل أو نصرة مذهب سابق", "يرون أن كل تفسير بالرأي محرم", "يرون الرأي مباحًا لكل أحد بلا شروط", "يقولون إن الحديث منسوخ"], "يقول العلماء إن التحذير في القول بلا علم أو بالهوى أو لنصرة مذهب، أما الاجتهاد في التفسير المبني على العربية والسنة وأقوال الصحابة وأسباب النزول والعلوم فمحمود، وتدل الأخبار على أن الصحابة أنفسهم فسروا بالرأي، وقد وضع العلماء شروطًا للمفسر منها علوم اللغة."] },

  { id: "xtf-012", s: "tafsir", g: 4, d: 7, t: ["methodology", "tafsir-ishari"], src: "al-Taftāzānī, Sharḥ al-ʿAqāʾid al-Nasafiyya; al-Suyūṭī, al-Itqān, naw‘ 78; Ibn al-Ṣalāḥ, Fatāwā",
    en: ["Under what conditions did Sunni scholars accept ishārī (allusive) interpretation of the Quran?", ["That it does not contradict the apparent meaning, has a supporting proof in the sharīʿa or language, and is not claimed to be the only meaning", "That it is accepted whenever the commentator claims inspiration", "That it replaces the apparent meaning entirely", "It was never accepted by any scholar"], "Scholars such as al-Taftāzānī and al-Suyūṭī accepted allusive readings from the mystics on conditions: no conflict with the literal sense or the sharīʿa, a supporting reason, and no claim that this is the intended meaning to the exclusion of the apparent one. Claims that the apparent meaning has no force were condemned as deviation."],
    de: ["Unter welchen Bedingungen nahmen sunnitische Gelehrte die ishārī-Auslegung (andeutende Auslegung) des Korans an?", ["Dass sie dem äußeren Sinn nicht widerspricht, einen stützenden Beleg in der Scharia oder Sprache hat und nicht als einziger Sinn behauptet wird", "Dass sie immer angenommen wird, wenn der Kommentator Eingebung beansprucht", "Dass sie den äußeren Sinn völlig ersetzt", "Sie wurde von keinem Gelehrten je angenommen"], "Gelehrte wie at-Taftāzānī und as-Suyūṭī nahmen andeutende Lesungen der Mystiker unter Bedingungen an: kein Widerspruch zum Wortsinn oder zur Scharia, ein stützender Grund und keine Behauptung, dies sei der gemeinte Sinn unter Ausschluss des äußeren. Die Behauptung, der äußere Sinn habe keine Geltung, wurde als Abweichung verurteilt."],
    ar: ["بأي شروط قبل علماء السنة التفسير الإشاري للقرآن؟", ["ألا يخالف المعنى الظاهر وأن يكون له شاهد من الشرع أو اللغة وألا يُزعم أنه المعنى الوحيد", "يُقبل متى ادعى المفسر الإلهام", "أن يحل محل المعنى الظاهر كليًّا", "لم يقبله أحد من العلماء"], "قبل علماء كالتفتازاني والسيوطي المعاني الإشارية عند أهل التصوف بشروط: ألا تعارض المعنى الظاهر أو الشرع، وأن يكون لها شاهد، وألا يُدّعى أنها المراد دون الظاهر، وأُنكر ادعاء أن الظاهر لا حكم له وعُدّ انحرافًا."] },

  { id: "xtf-013", s: "tafsir", g: 4, d: 7, t: ["methodology", "tabiun-tafsir"], tr: ["comparative"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr; al-Suyūṭī, al-Itqān, naw‘ 78",
    en: ["What is the scholarly position on the explanations of the Successors (tābiʿūn) as evidence in tafsīr?", ["When they agree, their explanation is a proof; when they differ, one view is not a proof against another and the choice is made by the Quran, Sunna, language and the Companions’ statements", "Their explanations are always binding", "Their explanations are never to be cited", "Only the Companions’ statements are cited, never the Successors’"], "Two reports from Aḥmad concern whether the Successors’ tafsīr is a proof. Ibn Taymiyya sums up: where they agree, it is not to be disputed; where they disagree, the view of one is not authoritative against that of another, and one turns to the language, the Quran and the Sunna. In practice classical commentaries cite them heavily."],
    de: ["Wie lautet die gelehrte Position zu den Erklärungen der Nachfolger (tābiʿūn) als Beleg im Tafsīr?", ["Wo sie übereinstimmen, ist ihre Erklärung ein Beleg; wo sie sich unterscheiden, ist die Ansicht des einen kein Beleg gegen die des anderen, und die Wahl trifft man nach Koran, Sunna, Sprache und Aussagen der Gefährten", "Ihre Erklärungen sind immer verbindlich", "Ihre Erklärungen sind nie zu zitieren", "Nur die Aussagen der Gefährten werden zitiert, nie die der Nachfolger"], "Zwei Berichte von Aḥmad betreffen die Frage, ob der Tafsīr der Nachfolger ein Beleg ist. Ibn Taimiyya fasst zusammen: Wo sie übereinstimmen, ist nicht zu streiten; wo sie sich unterscheiden, hat die Ansicht des einen gegenüber der des anderen keine Autorität, und man wendet sich der Sprache, dem Koran und der Sunna zu. In der Praxis zitieren klassische Kommentare sie ausgiebig."],
    ar: ["ما موقف العلماء من أقوال التابعين حجةً في التفسير؟", ["إذا اتفقوا فتفسيرهم حجة، وإذا اختلفوا فلا يكون قول بعضهم حجة على بعض ويُرجَع إلى القرآن والسنة واللغة وأقوال الصحابة", "أقوالهم ملزمة دائمًا", "لا يجوز الاستشهاد بأقوالهم أبدًا", "يُستشهد بأقوال الصحابة وحدها ولا يُستشهد بالتابعين"], "عن أحمد روايتان في كون تفسير التابعين حجة، ولخّص ابن تيمية أنهم إذا اجتمعوا فلا يُرتاب في ذلك، وإن اختلفوا فلا يكون قول بعضهم حجة على بعض ويُرجَع إلى اللغة والقرآن والسنة، وتكثر المصنفات الكلاسيكية من النقل عنهم."] },

  { id: "xtf-014", s: "tafsir", g: 4, d: 6, t: ["tafsir-schools", "companions"], src: "al-Dhahabī, al-Tafsīr wa-l-Mufassirūn; al-Suyūṭī, al-Itqān, naw‘ 78",
    en: ["Which Companion is regarded as the founder of the Makkan school of tafsīr, and which Successors belong to it?", ["Ibn ʿAbbās; Mujāhid, ʿIkrima, Saʿīd ibn Jubayr, ʿAṭāʾ and Ṭāwūs", "Ibn Masʿūd; ʿAlqama, Masrūq and al-Aswad", "Ubayy ibn Kaʿb; Zayd ibn Aslam and Abū al-ʿĀliya", "ʿAlī ibn Abī Ṭālib; al-Ḥasan al-Baṣrī and Qatāda"], "Ibn ʿAbbās, called the interpreter of the Quran, taught in Makka, and his students Mujāhid, ʿIkrima, Saʿīd ibn Jubayr, ʿAṭāʾ ibn Abī Rabāḥ and Ṭāwūs formed the Makkan school. Ibn Masʿūd stands at the head of the Iraqi school (ʿAlqama, Masrūq, al-Aswad) and Ubayy ibn Kaʿb at the head of the Madinan one (Zayd ibn Aslam, Abū al-ʿĀliya)."],
    de: ["Welcher Gefährte gilt als Begründer der mekkanischen Schule des Tafsīr, und welche Nachfolger gehören dazu?", ["Ibn ʿAbbās; Muǧāhid, ʿIkrima, Saʿīd ibn Ǧubair, ʿAṭāʾ und Ṭāwūs", "Ibn Masʿūd; ʿAlqama, Masrūq und al-Aswad", "Ubaiy ibn Kaʿb; Zaid ibn Aslam und Abū l-ʿĀliya", "ʿAlī ibn Abī Ṭālib; al-Ḥasan al-Baṣrī und Qatāda"], "Ibn ʿAbbās, der Dolmetscher des Korans genannt, lehrte in Mekka, und seine Schüler Muǧāhid, ʿIkrima, Saʿīd ibn Ǧubair, ʿAṭāʾ ibn Abī Rabāḥ und Ṭāwūs bildeten die mekkanische Schule. Ibn Masʿūd steht an der Spitze der irakischen Schule (ʿAlqama, Masrūq, al-Aswad) und Ubaiy ibn Kaʿb an der Spitze der medinensischen (Zaid ibn Aslam, Abū l-ʿĀliya)."],
    ar: ["أي صحابي يُعدّ مؤسس مدرسة التفسير المكية وأي تابعين ينتمون إليها؟", ["ابن عباس؛ مجاهد وعكرمة وسعيد بن جبير وعطاء وطاووس", "ابن مسعود؛ علقمة ومسروق والأسود", "أُبيّ بن كعب؛ زيد بن أسلم وأبو العالية", "علي بن أبي طالب؛ الحسن البصري وقتادة"], "علّم ابن عباس ترجمان القرآن في مكة، وكوّن تلاميذه مجاهد وعكرمة وسعيد بن جبير وعطاء بن أبي رباح وطاووس المدرسة المكية، وعلى رأس المدرسة العراقية ابن مسعود (علقمة ومسروق والأسود) وعلى رأس المدنية أُبيّ بن كعب (زيد بن أسلم وأبو العالية)."] },

  { id: "xtf-015", s: "tafsir", g: 4, d: 6, t: ["classical-works", "ahkam-works"], tr: ["hanafi", "maliki", "shafii"], src: "al-Jaṣṣāṣ, Aḥkām al-Qurʾān; Ibn al-ʿArabī, Aḥkām al-Qurʾān; al-Kiyā al-Harrāsī, Aḥkām al-Qurʾān; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān",
    en: ["Which pairing of the classical Aḥkām al-Qurʾān works with their authors’ schools is correct?", ["al-Jaṣṣāṣ: Ḥanafī; Ibn al-ʿArabī: Mālikī; al-Kiyā al-Harrāsī: Shāfiʿī", "al-Jaṣṣāṣ: Shāfiʿī; Ibn al-ʿArabī: Ḥanafī; al-Kiyā: Mālikī", "al-Jaṣṣāṣ: Mālikī; Ibn al-ʿArabī: Shāfiʿī; al-Kiyā: Ḥanbalī", "All three: Ḥanbalī"], "These works group the legal verses and their interpretation by the author’s school: Abū Bakr al-Jaṣṣāṣ (d. 370 AH) is Ḥanafī, Abū Bakr ibn al-ʿArabī (d. 543 AH) is Mālikī, and al-Kiyā al-Harrāsī (d. 504 AH) is Shāfiʿī. Al-Qurṭubī (d. 671 AH) wrote a broader commentary on legal rulings, in the Mālikī tradition."],
    de: ["Welche Zuordnung der klassischen Aḥkām-al-Qurʾān-Werke zu den Schulen ihrer Autoren ist richtig?", ["Al-Ǧaṣṣāṣ: Hanafit; Ibn al-ʿArabī: Malikit; al-Kiyā al-Harrāsī: Schafiit", "Al-Ǧaṣṣāṣ: Schafiit; Ibn al-ʿArabī: Hanafit; al-Kiyā: Malikit", "Al-Ǧaṣṣāṣ: Malikit; Ibn al-ʿArabī: Schafiit; al-Kiyā: Hanbalit", "Alle drei: Hanbalit"], "Diese Werke ordnen die Rechtsverse und ihre Auslegung nach der Schule des Autors: Abū Bakr al-Ǧaṣṣāṣ (gest. 370 n. H.) ist Hanafit, Abū Bakr Ibn al-ʿArabī (gest. 543 n. H.) ist Malikit und al-Kiyā al-Harrāsī (gest. 504 n. H.) ist Schafiit. Al-Qurṭubī (gest. 671 n. H.) schrieb einen weiteren Kommentar zu Rechtsurteilen in der malikitischen Tradition."],
    ar: ["أي اقتران بين كتب «أحكام القرآن» ومذاهب مؤلفيها صحيح؟", ["الجصاص: حنفي؛ ابن العربي: مالكي؛ الكيا الهراسي: شافعي", "الجصاص: شافعي؛ ابن العربي: حنفي؛ الكيا: مالكي", "الجصاص: مالكي؛ ابن العربي: شافعي؛ الكيا: حنبلي", "الثلاثة حنابلة"], "تجمع هذه الكتب آيات الأحكام وتفسيرها على مذهب مؤلفيها: أبو بكر الجصاص (ت 370هـ) حنفي وأبو بكر ابن العربي (ت 543هـ) مالكي والكيا الهراسي (ت 504هـ) شافعي، وللقرطبي (ت 671هـ) تفسير أوسع في الأحكام على مذهب مالك."] },

  { id: "xtf-016", s: "tafsir", g: 4, d: 6, t: ["classical-works", "munasabat"], src: "al-Biqāʿī, Naẓm al-Durar fī Tanāsub al-Āyāt wa-l-Suwar; Ibn al-Zubayr al-Gharnāṭī, al-Burhān fī Munāsabat Tartīb Suwar al-Qurʾān",
    en: ["Which commentary is best known for its detailed study of the links (munāsabāt) between verses and between sūras?", ["Naẓm al-Durar fī Tanāsub al-Āyāt wa-l-Suwar by al-Biqāʿī", "al-Muḥarrar al-Wajīz by Ibn ʿAṭiyya", "Tafsīr al-Jalālayn", "Fatḥ al-Qadīr by al-Shawkānī"], "Burhān al-Dīn al-Biqāʿī (d. 885 AH) devoted his commentary to showing the coherence of each verse with what precedes and follows and the order of the sūras. Ibn al-Zubayr al-Gharnāṭī wrote a shorter classical study on the sequence of the sūras. The other commentaries cited are better known for language, brevity and a mix of riwāya and dirāya."],
    de: ["Welcher Kommentar ist für seine detaillierte Untersuchung der Verbindungen (munāsabāt) zwischen Versen und zwischen Suren am bekanntesten?", ["Naẓm ad-Durar fī Tanāsub al-Āyāt wa-s-Suwar von al-Biqāʿī", "Al-Muḥarrar al-Waǧīz von Ibn ʿAṭiyya", "Tafsīr al-Ǧalālain", "Fatḥ al-Qadīr von aš-Šaukānī"], "Burhān ad-Dīn al-Biqāʿī (gest. 885 n. H.) widmete seinen Kommentar dem Nachweis des Zusammenhangs jedes Verses mit dem Vorangehenden und Folgenden sowie der Ordnung der Suren. Ibn az-Zubair al-Ġarnāṭī schrieb eine kürzere klassische Studie über die Abfolge der Suren. Die anderen genannten Kommentare sind eher für Sprache, Kürze und eine Mischung aus Riwāya und Dirāya bekannt."],
    ar: ["أي تفسير يشتهر بدراسته التفصيلية للمناسبات بين الآيات وبين السور؟", ["نظم الدرر في تناسب الآيات والسور للبقاعي", "المحرر الوجيز لابن عطية", "تفسير الجلالين", "فتح القدير للشوكاني"], "خصّص برهان الدين البقاعي (ت 885هـ) تفسيره لبيان ارتباط كل آية بما قبلها وما بعدها وترتيب السور، وكتب ابن الزبير الغرناطي دراسة كلاسيكية أصغر في تتابع السور، أما بقية التفاسير فأشهر بالحديث عن اللغة والإيجاز والجمع بين الرواية والدراية."] },

  { id: "xtf-017", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "Abū Ḥayyān, al-Baḥr al-Muḥīṭ, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["Which commentary on the Quran is known for its grammatical and linguistic analysis, by the Andalusian grammarian Abū Ḥayyān?", ["al-Baḥr al-Muḥīṭ", "Rūḥ al-Maʿānī", "Mafātīḥ al-Ghayb", "Maʿālim al-Tanzīl"], "Abū Ḥayyān al-Gharnāṭī (d. 745 AH) wrote al-Baḥr al-Muḥīṭ, a tafsīr in which he discusses grammar, readings and linguistics at length, and he criticised grammatical errors in earlier tafsīrs. Rūḥ al-Maʿānī is by al-Alūsī, Mafātīḥ al-Ghayb by al-Rāzī and Maʿālim al-Tanzīl by al-Baghawī."],
    de: ["Welcher Korankommentar des andalusischen Grammatikers Abū Ḥayyān ist für seine grammatische und sprachliche Analyse bekannt?", ["Al-Baḥr al-Muḥīṭ", "Rūḥ al-Maʿānī", "Mafātīḥ al-Ġaib", "Maʿālim at-Tanzīl"], "Abū Ḥayyān al-Ġarnāṭī (gest. 745 n. H.) schrieb al-Baḥr al-Muḥīṭ, einen Tafsīr, in dem er Grammatik, Lesarten und Sprachwissenschaft ausführlich erörtert und grammatische Fehler früherer Tafsīre kritisierte. Rūḥ al-Maʿānī stammt von al-Alūsī, Mafātīḥ al-Ġaib von ar-Rāzī und Maʿālim at-Tanzīl von al-Baġawī."],
    ar: ["أي تفسير للنحوي الأندلسي أبي حيان يشتهر بالتحليل النحوي واللغوي؟", ["البحر المحيط", "روح المعاني", "مفاتيح الغيب", "معالم التنزيل"], "ألّف أبو حيان الغرناطي (ت 745هـ) «البحر المحيط» وأسهب فيه في النحو والقراءات واللغة وانتقد أخطاء نحوية في تفاسير سابقة، أما «روح المعاني» فللألوسي و«مفاتيح الغيب» للرازي و«معالم التنزيل» للبغوي."] },

  { id: "xtf-018", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Dhahabī, al-Tafsīr wa-l-Mufassirūn; Ibn Khallikān, Wafayāt al-Aʿyān",
    en: ["Which commentary is known for its extensive discussion of theology, philosophy and the sciences, and is attributed to Fakhr al-Dīn al-Rāzī?", ["Mafātīḥ al-Ghayb (al-Tafsīr al-Kabīr)", "al-Baḥr al-Muḥīṭ", "Aḥkām al-Qurʾān", "Taʾwīlāt Ahl al-Sunna"], "Fakhr al-Dīn al-Rāzī (d. 606 AH) wrote Mafātīḥ al-Ghayb, which discusses theology, logic, cosmology and many other topics beside the verses, with attention to the links between verses. It is said to have been completed by his students. Taʾwīlāt Ahl al-Sunna is by al-Māturīdī, and Aḥkām al-Qurʾān is the name of several works on legal verses."],
    de: ["Welcher Kommentar ist für seine ausführliche Erörterung von Theologie, Philosophie und Wissenschaften bekannt und wird Faḫr ad-Dīn ar-Rāzī zugeschrieben?", ["Mafātīḥ al-Ġaib (at-Tafsīr al-Kabīr)", "Al-Baḥr al-Muḥīṭ", "Aḥkām al-Qurʾān", "Taʾwīlāt Ahl as-Sunna"], "Faḫr ad-Dīn ar-Rāzī (gest. 606 n. H.) schrieb Mafātīḥ al-Ġaib, das neben den Versen Theologie, Logik, Kosmologie und viele weitere Themen erörtert, mit Aufmerksamkeit für die Verbindungen zwischen Versen. Es soll von seinen Schülern vollendet worden sein. Taʾwīlāt Ahl as-Sunna stammt von al-Māturīdī, und Aḥkām al-Qurʾān ist der Name mehrerer Werke über Rechtsverse."],
    ar: ["أي تفسير يشتهر بإسهابه في علم الكلام والفلسفة والعلوم ويُنسب إلى فخر الدين الرازي؟", ["مفاتيح الغيب (التفسير الكبير)", "البحر المحيط", "أحكام القرآن", "تأويلات أهل السنة"], "ألّف فخر الدين الرازي (ت 606هـ) «مفاتيح الغيب» وفيه بحث في الكلام والمنطق والكون وغيرها إلى جانب الآيات مع عناية بمناسبات الآيات، ويقال إن تلاميذه أتموه، أما «تأويلات أهل السنة» فللماتريدي و«أحكام القرآن» اسم لعدة كتب في آيات الأحكام."] },

  { id: "xtf-019", s: "tafsir", g: 4, d: 7, t: ["classical-works", "tafsir-authors"], tr: ["maturidi"], src: "al-Māturīdī, Taʾwīlāt Ahl al-Sunna (Taʾwīlāt al-Qurʾān); al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["What is the Taʾwīlāt Ahl al-Sunna (Taʾwīlāt al-Qurʾān) and who wrote it?", ["A commentary by Abū Manṣūr al-Māturīdī (d. 333 AH) of Samarkand, an early work of the Sunni rational tradition that gave rise to the Māturīdī school", "A commentary by Abū al-Ḥasan al-Ashʿarī on creed only", "A commentary by al-Ṭabarī on the readings", "A collection of the sayings of Ibn ʿAbbās"], "Al-Māturīdī’s commentary explains the Quran with attention to language and reason, defending the positions later identified as Māturīdī in creed, and it often gives several possible interpretations. It is among the earliest surviving Sunni commentaries from Central Asia and is a major source for the school in the Ḥanafī world."],
    de: ["Was ist die Taʾwīlāt Ahl as-Sunna (Taʾwīlāt al-Qurʾān) und wer schrieb sie?", ["Ein Kommentar von Abū Manṣūr al-Māturīdī (gest. 333 n. H.) aus Samarkand, ein frühes Werk der sunnitischen rationalen Tradition, aus der die māturīdītische Schule hervorging", "Ein Kommentar von Abū l-Ḥasan al-Ašʿarī nur zum Glauben", "Ein Kommentar von aṭ-Ṭabarī zu den Lesarten", "Eine Sammlung von Aussprüchen Ibn ʿAbbās’"], "Al-Māturīdīs Kommentar erklärt den Koran mit Blick auf Sprache und Vernunft und verteidigt die später als māturīditisch bezeichneten Positionen im Glauben; er bietet oft mehrere mögliche Auslegungen. Er gehört zu den frühesten erhaltenen sunnitischen Kommentaren aus Zentralasien und ist eine Hauptquelle der Schule in der hanafitischen Welt."],
    ar: ["ما «تأويلات أهل السنة» (تأويلات القرآن) ومن ألّفها؟", ["تفسير لأبي منصور الماتريدي (ت 333هـ) السمرقندي، من أوائل أعمال التقليد السني العقلي الذي نشأ عنه المذهب الماتريدي", "تفسير لأبي الحسن الأشعري في العقيدة وحدها", "تفسير للطبري في القراءات", "مجموعة من أقوال ابن عباس"], "يفسر الماتريدي القرآن بعناية باللغة والعقل ويدافع عن مواقف عُرفت لاحقًا بالماتريدية في العقيدة، وكثيرًا ما يورد عدة تأويلات ممكنة، وهو من أقدم التفاسير السنية الباقية من آسيا الوسطى ومصدر رئيس للمذهب في العالم الحنفي."] },

  { id: "xtf-020", s: "tafsir", g: 4, d: 7, t: ["classical-works", "tafsir-authors"], src: "al-Baghawī, Maʿālim al-Tanzīl, introduction; al-Thaʿlabī, al-Kashf wa-l-Bayān; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["How is al-Baghawī’s Maʿālim al-Tanzīl related to al-Thaʿlabī’s al-Kashf wa-l-Bayān?", ["Al-Baghawī abridged it, removing the weak and fabricated reports and adding hadith of the Ṣaḥīḥayn and the Sunan", "Al-Baghawī copied it unchanged", "Al-Thaʿlabī abridged al-Baghawī’s commentary", "The two works have no relation"], "Al-Baghawī (d. 516 AH) based Maʿālim al-Tanzīl on the commentary of his teacher al-Thaʿlabī (d. 427 AH), which was rich in reports but also contained weak and invented ones. He retained its benefits while deleting the fabricated material and adding sounder reports, so that the work became a widely used commentary bi-l-maʾthūr."],
    de: ["In welchem Verhältnis steht al-Baġawīs Maʿālim at-Tanzīl zu aṯ-Ṯaʿlabīs al-Kašf wa-l-Bayān?", ["Al-Baġawī kürzte es, entfernte die schwachen und erfundenen Berichte und fügte Hadithe aus den Ṣaḥīḥain und den Sunan hinzu", "Al-Baġawī schrieb es unverändert ab", "Aṯ-Ṯaʿlabī kürzte al-Baġawīs Kommentar", "Die beiden Werke haben keine Beziehung"], "Al-Baġawī (gest. 516 n. H.) baute Maʿālim at-Tanzīl auf dem Kommentar seines Lehrers aṯ-Ṯaʿlabī (gest. 427 n. H.) auf, der reich an Berichten war, aber auch schwache und erfundene enthielt. Er behielt seinen Nutzen bei, strich das Erfundene und fügte gesündere Berichte hinzu, sodass das Werk ein viel genutzter Kommentar bi-l-maʾṯūr wurde."],
    ar: ["كيف ترتبط «معالم التنزيل» للبغوي بـ«الكشف والبيان» للثعلبي؟", ["اختصره البغوي وحذف الأخبار الضعيفة والموضوعة وزاد أحاديث الصحيحين والسنن", "نسخه البغوي دون تغيير", "اختصر الثعلبي تفسير البغوي", "لا علاقة بين الكتابين"], "بنى البغوي (ت 516هـ) «معالم التنزيل» على تفسير شيخه الثعلبي (ت 427هـ) الغني بالأخبار والذي اشتمل أيضًا على ضعيف وموضوع، فأبقى فوائده وحذف المختلق وأضاف روايات أصح، فصار تفسيرًا بالمأثور كثير التداول."] },

  { id: "xtf-021", s: "tafsir", g: 4, d: 7, t: ["mutashabih-lafzi", "similar-verses"], src: "al-Karmānī, al-Burhān fī Mutashābih al-Qurʾān; al-Iskāfī, Durrat al-Tanzīl; Zakariyyā al-Anṣārī, Fatḥ al-Raḥmān", v: "28:20", w: 2,
    en: ["In this verse the man comes first (‘a man came from the farthest part of the city’), whereas in 36:20 the place comes first. What is the explanation given by the commentators?", ["In al-Qaṣaṣ the focus is on the man and his warning to Mūsā, while in Yā Sīn the emphasis is on the distance from which he came to support the messengers", "The scribes mistakenly transposed the words", "The two verses refer to the same man in different languages", "The order is for the rhyme alone"], "The two verses describe the arrival of a man who tries to help, but each places its emphasis differently. In 28:20 the man is mentioned first because the interest is in what he says to Mūsā about the plot. In 36:20 the place comes first, showing that even from the farthest part of the city a man came with concern for the messengers, though the leaders had rejected them. Commentators such as al-Karmānī give similar accounts."],
    de: ["In diesem Vers steht zuerst der Mann (‚ein Mann kam vom entlegensten Ende der Stadt‘), während in 36:20 zuerst der Ort steht. Welche Erklärung geben die Kommentatoren?", ["In al-Qaṣaṣ liegt der Schwerpunkt auf dem Mann und seiner Warnung an Mūsā, in Yā Sīn dagegen auf der Entfernung, aus der er kam, um die Gesandten zu unterstützen", "Die Schreiber haben die Wörter versehentlich vertauscht", "Die beiden Verse meinen denselben Mann in verschiedenen Sprachen", "Die Reihenfolge dient nur dem Reim"], "Beide Verse beschreiben das Eintreffen eines Mannes, der zu helfen versucht, doch jeder legt den Schwerpunkt anders. In 28:20 steht der Mann zuerst, da es um das geht, was er Mūsā über den Anschlag sagt. In 36:20 steht der Ort zuerst: Selbst vom entlegensten Ende der Stadt kam ein Mann in Sorge um die Gesandten, obwohl die Anführer sie abgelehnt hatten. Kommentatoren wie al-Karmānī geben ähnliche Darstellungen."],
    ar: ["في هذه الآية تقدم الرجل على المكان بينما في يس 20 تقدم المكان. ما التفسير الذي يذكره المفسرون؟", ["في القصص التركيز على الرجل ونصيحته لموسى، وفي يس على بُعد المكان الذي جاء منه لنصرة المرسلين", "أخطأ الكتبة فقدموا وأخروا", "الآيتان في الرجل نفسه بلغتين مختلفتين", "الترتيب للفاصلة وحدها"], "تصف الآيتان مجيء رجل يحاول النصرة لكن لكل آية تركيزًا، ففي القصص قُدم الرجل لأن الاهتمام بما قاله لموسى من أمر المؤامرة، وفي يس قُدم المكان لبيان أن من أقصى المدينة جاء رجل غيور على المرسلين بعد أن ردّهم أهل البلد. ويذكر الكرماني وغيره نحو ذلك."] },

  { id: "xtf-022", s: "tafsir", g: 4, d: 7, t: ["tafsir-linguistic", "wau-thamaniya"], src: "Ibn Hishām, Mughnī al-Labīb, on the wāw al-thamāniya; al-Zamakhsharī, al-Kashshāf, on 18:22; al-Suhaylī, Nataʾij al-Fikr", v: "18:22", w: 13,
    en: ["The group of three and five is described without a conjunction before ‘their dog’, whereas the group of seven has the word ‘eighth’ with a wāw. What do some grammarians call this wāw, and how do others explain it?", ["‘Wāw of the eight’ (wāw al-thamāniya), a feature some thought the Arabs used for the number eight; others take it as an ordinary wāw of the circumstance that confirms the statement", "A wāw of oath", "A wāw of the accusative", "A wāw that changes the meaning into a question"], "Some grammarians, like Ibn Khālawayh, spoke of a wāw al-thamāniya found with the number eight (here and in 9:112, 39:73, 66:5), but many, including Ibn Hishām, did not accept it as a rule. Al-Zamakhsharī takes it as the wāw of the circumstance that confirms the description of the group, which suits the claim that the seven are those whose count is correct."],
    de: ["Die Gruppe von drei und fünf wird ohne Konjunktion vor ‚ihr Hund‘ beschrieben, während die Gruppe von sieben das Wort ‚achter‘ mit Wāw hat. Wie nennen manche Grammatiker dieses Wāw, und wie erklären es andere?", ["‚Wāw der Acht‘ (wāw aṯ-ṯamāniya), ein Merkmal, das nach manchen die Araber bei der Zahl Acht gebrauchten; andere sehen darin ein gewöhnliches Wāw des Umstands, das die Aussage bekräftigt", "Ein Wāw des Schwurs", "Ein Wāw des Akkusativs", "Ein Wāw, das den Sinn in eine Frage verwandelt"], "Manche Grammatiker wie Ibn Ḫālawaih sprachen von einem Wāw aṯ-ṯamāniya bei der Zahl Acht (hier und in 9:112, 39:73, 66:5), doch viele, darunter Ibn Hišām, erkannten es nicht als Regel an. Az-Zamaḫšarī nimmt es als Wāw des Umstands, das die Beschreibung der Gruppe bekräftigt, was zur Annahme passt, dass die Sieben diejenigen sind, deren Zahl stimmt."],
    ar: ["وُصفت مجموعة الثلاثة والخمسة بلا حرف عطف قبل كلبهم، وفي مجموعة السبعة جاءت كلمة «ثامنهم» بواو. ماذا يسمي بعض النحاة هذه الواو وكيف يفسرها غيرهم؟", ["«واو الثمانية» وهي ميزة ظنها بعضهم في العدد ثمانية عند العرب، وغيرهم يعدّها واو الحال المؤكدة للكلام", "واو القسم", "واو النصب", "واو تحول المعنى إلى سؤال"], "قال بعض النحاة كابن خالويه بواو الثمانية في العدد ثمانية (هنا والتوبة 112 والزمر 73 والتحريم 5)، لكن كثيرين منهم ابن هشام لم يقبلوها قاعدة. ويرى الزمخشري أنها واو الجملة الحالية المؤكدة لوصف المجموعة، وهذا يناسب القول بأن السبعة هم المقصودون بصحة العدد."] },

  { id: "xtf-023", s: "tafsir", g: 4, d: 6, t: ["asbab-and-tafsir", "sahih-reports"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr and Kitāb al-Ṣawm (hadith of Sahl ibn Saʿd on 2:187); Ibn Ḥajar, Fatḥ al-Bārī", v: "2:187", w: 42,
    en: ["According to the report from Sahl ibn Saʿd in al-Bukhārī, what happened with the highlighted words about the white thread and the black thread?", ["The verse was first revealed without the words ‘of the dawn’, so some men tied white and black threads to their feet to distinguish them; then those words were revealed to show that the threads mean the light of dawn and the dark of night", "The words were revealed before the rest of the verse", "The words were later removed from the verse", "The words were revealed in Makka"], "Sahl reports that men took two threads, one white and one black, and kept eating until they could tell them apart, until the words ‘of the dawn’ were revealed, so they knew that the threads signify night and day. ʿAdī ibn Ḥātim’s similar story also appears. It is a standard example of a later revelation clarifying an earlier one."],
    de: ["Was geschah nach dem Bericht von Sahl ibn Saʿd bei al-Buḫārī mit den markierten Worten über den weißen und den schwarzen Faden?", ["Der Vers wurde zuerst ohne die Worte ‚vom Morgengrauen‘ offenbart, sodass manche Männer einen weißen und einen schwarzen Faden an ihre Füße banden, um sie zu unterscheiden; dann wurden diese Worte offenbart, um zu zeigen, dass die Fäden das Licht der Morgenröte und das Dunkel der Nacht meinen", "Die Worte wurden vor dem Rest des Verses offenbart", "Die Worte wurden später aus dem Vers entfernt", "Die Worte wurden in Mekka offenbart"], "Sahl berichtet, Männer hätten zwei Fäden genommen, einen weißen und einen schwarzen, und weitergegessen, bis sie sie unterscheiden konnten, bis die Worte ‚vom Morgengrauen‘ offenbart wurden, sodass sie wussten, dass die Fäden Nacht und Tag bedeuten. Auch die ähnliche Geschichte von ʿAdī ibn Ḥātim ist überliefert. Es ist ein Standardbeispiel dafür, dass eine spätere Offenbarung eine frühere erläutert."],
    ar: ["بحسب رواية سهل بن سعد في صحيح البخاري، ماذا حدث بشأن الكلمات المظللة عن الخيط الأبيض والخيط الأسود؟", ["نزلت الآية أولًا بدون عبارة «من الفجر» فربط بعض الرجال خيطين أبيض وأسود في أرجلهم ليميزوهما، ثم نزلت العبارة فعلموا أن المراد بياض النهار وسواد الليل", "نزلت العبارة قبل بقية الآية", "حُذفت العبارة من الآية لاحقًا", "نزلت العبارة بمكة"], "روى سهل أن رجالًا ربطوا خيطين أبيض وأسود وظلوا يأكلون حتى يتبينا لهم ثم نزلت العبارة فعلموا أنما يعني الليل والنهار، وتُروى قصة مشابهة لعدي بن حاتم. وهي مثال معروف على وحي لاحق يبيّن سابقه."] },

  { id: "xtf-024", s: "tafsir", g: 4, d: 7, t: ["asbab-and-tafsir", "sahih-reports"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ḥajj and Kitāb al-Tafsīr (ʿĀʾisha and ʿUrwa on 2:158); Muslim, Ṣaḥīḥ, Kitāb al-Ḥajj", v: "2:158", w: 13,
    en: ["The words ‘no blame on him’ about going round al-Ṣafā and al-Marwa seem to make the rite optional. How did ʿĀʾisha explain them to ʿUrwa?", ["They were revealed because the Anṣār hesitated to walk between them, having done so for an idol; the words remove the hesitation and do not make the rite optional, and the Prophet established it", "They mean that the rite is optional and may be omitted", "They were revealed about the Quraysh in Makka only", "They were abrogated"], "ʿUrwa asked ʿĀʾisha whether the words meant that going between the two hills was optional. She replied that if that were the meaning the text would read ‘no blame on him not to’; the words were revealed because the Anṣār, who used to hail Manāt, felt uneasy, and the Prophet instituted the walk. Most jurists consider it a pillar or an obligation; the Ḥanafīs consider it an obligation whose omission can be compensated for by an offering."],
    de: ["Die Worte ‚kein Vorwurf trifft ihn‘ beim Gehen zwischen aṣ-Ṣafā und al-Marwa scheinen den Ritus zur Wahl zu stellen. Wie erklärte ʿĀʾiša sie ʿUrwa?", ["Sie wurden offenbart, weil die Anṣār zögerten, zwischen ihnen zu gehen, da sie es einst für ein Götzenbild getan hatten; die Worte nehmen das Zögern und machen den Ritus nicht freiwillig, und der Prophet führte ihn ein", "Sie bedeuten, dass der Ritus freiwillig ist und ausgelassen werden darf", "Sie wurden nur über die Quraiš in Mekka offenbart", "Sie wurden aufgehoben"], "ʿUrwa fragte ʿĀʾiša, ob die Worte bedeuteten, das Gehen zwischen den beiden Hügeln sei freiwillig. Sie antwortete, wäre das der Sinn, hieße es ‚kein Vorwurf trifft ihn, es nicht zu tun‘; die Worte wurden offenbart, weil die Anṣār, die Manāt anzurufen pflegten, sich unbehaglich fühlten, und der Prophet führte das Gehen ein. Die meisten Juristen sehen es als Säule oder Pflicht; die Hanafiten sehen es als Pflicht, deren Auslassung durch ein Opfer ausgeglichen werden kann."],
    ar: ["عبارة «لا جناح عليه» في الطواف بين الصفا والمروة توحي بأن الشعيرة اختيارية. كيف فسّرتها عائشة لعروة؟", ["نزلت لأن الأنصار تحرجوا من السعي بينهما لأنهم كانوا يفعلونه لصنم، فرفعت الحرج ولا تجعل الشعيرة اختيارية، وقد سنّ النبي ﷺ السعي", "معناها أن الشعيرة اختيارية ويجوز تركها", "نزلت في قريش بمكة فقط", "نُسخت"], "سأل عروة عائشة هل تعني العبارة أن السعي اختياري، فقالت لو كان كذلك لقال لا جناح عليه ألا يطوف بهما، وإنما نزلت لأن الأنصار كانوا يُهلّون لمناة فتحرجوا فنزلت، وسنّ النبي ﷺ الطواف بينهما. وأكثر الفقهاء يعدّونه ركنًا أو واجبًا، والحنفية واجب ينجبر تركه بدم."] },

  { id: "xtf-025", s: "tafsir", g: 4, d: 6, t: ["asbab-and-tafsir", "sahih-reports"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tafsīr (ʿĀʾisha’s explanation of 4:3); Muslim, Ṣaḥīḥ, Kitāb al-Tafsīr", v: "4:3", w: 6,
    en: ["How did ʿĀʾisha explain, in the report in al-Bukhārī, the link between the fear of being unjust to orphans and permission to marry two, three or four women?", ["The verse concerns a guardian of an orphan girl who wants to marry her for her property without giving her a fair dowry; he is told to marry other women instead", "The verse concerns an orphan boy who wishes to marry several women", "The verse is only about inheritance of orphans", "The verse is about adoption"], "ʿUrwa asked ʿĀʾisha about the verse, and she explained that it concerns an orphan girl under a man’s care, who is attracted to her property and beauty and wants to marry her without giving her the full dower; he was forbidden from doing so unless he does justice, and told to marry other women. This is cited in discussions of how the occasion clarifies a verse’s wording."],
    de: ["Wie erklärte ʿĀʾiša im Bericht bei al-Buḫārī den Zusammenhang zwischen der Furcht, Waisen Unrecht zu tun, und der Erlaubnis, zwei, drei oder vier Frauen zu heiraten?", ["Der Vers betrifft den Vormund eines Waisenmädchens, der sie wegen ihres Vermögens heiraten will, ohne ihr eine angemessene Brautgabe zu geben; er wird angewiesen, stattdessen andere Frauen zu heiraten", "Der Vers betrifft einen Waisenjungen, der mehrere Frauen heiraten möchte", "Der Vers handelt nur vom Erbe der Waisen", "Der Vers handelt von der Adoption"], "ʿUrwa fragte ʿĀʾiša nach dem Vers, und sie erklärte, er betreffe ein Waisenmädchen in der Obhut eines Mannes, das ihn wegen ihres Vermögens und ihrer Schönheit reizt und das er ohne volle Brautgabe heiraten will; ihm wurde dies verboten, außer er handle gerecht, und er wurde angewiesen, andere Frauen zu heiraten. Dies wird in den Erörterungen angeführt, wie der Anlass den Wortlaut eines Verses erhellt."],
    ar: ["كيف فسّرت عائشة في رواية البخاري العلاقة بين خوف الظلم في اليتامى وإباحة نكاح مثنى وثلاث ورباع؟", ["الآية في ولي يتيمة يرغب في نكاحها لمالها دون أن يعطيها صداقًا عادلًا فيُنهى ويؤمر بنكاح غيرها", "الآية في يتيم يريد نكاح عدة نساء", "الآية في ميراث اليتامى فقط", "الآية في التبني"], "سأل عروة عائشة عن الآية فبيّنت أنها في اليتيمة في حجر وليها تعجبه بمالها وجمالها فيريد أن ينكحها بغير أن يقسط في صداقها، فنُهوا عن ذلك إلا أن يقسطوا وأُمروا بنكاح ما طاب من غيرها. ويُستشهد بها في بيان أثر السبب في توضيح لفظ الآية."] },

  { id: "xtf-026", s: "tafsir", g: 4, d: 7, t: ["maqasid", "ibn-ashur"], tr: ["comparative"], src: "Ibn ʿĀshūr, Maqāṣid al-Sharīʿa al-Islāmiyya, ch. on the general purposes (al-maqāṣid al-ʿāmma)",
    en: ["Which general characteristics (not specific interests) does Ibn ʿĀshūr list in his Maqāṣid al-Sharīʿa al-Islāmiyya as the broader intentions of the sharīʿa?", ["Natural disposition (fiṭra), ease and tolerance (samāḥa), equality, and freedom", "Obedience, silence, secrecy and unity", "Prayer, fasting, zakāt and pilgrimage", "Honour, wealth, family and trade"], "Ibn ʿĀshūr (d. 1973) goes beyond the five necessities and describes the sharīʿa’s general features: it is consistent with the human natural disposition (fiṭra), is built on ease and tolerance (samāḥa), on equality (musāwāt) among people, and on freedom (ḥurriyya) in what the law does not restrict. These serve as criteria for judging the purpose of rulings."],
    de: ["Welche allgemeinen Merkmale (nicht bestimmte Interessen) nennt Ibn ʿĀšūr in seinen Maqāṣid aš-Šarīʿa al-Islāmiyya als weitere Absichten der Scharia?", ["Natürliche Veranlagung (fiṭra), Leichtigkeit und Nachsicht (samāḥa), Gleichheit und Freiheit", "Gehorsam, Schweigen, Geheimhaltung und Einheit", "Gebet, Fasten, Zakāt und Pilgerfahrt", "Ehre, Reichtum, Familie und Handel"], "Ibn ʿĀšūr (gest. 1973) geht über die fünf Notwendigkeiten hinaus und beschreibt die allgemeinen Züge der Scharia: Sie stimmt mit der natürlichen Veranlagung des Menschen (fiṭra) überein, beruht auf Leichtigkeit und Nachsicht (samāḥa), auf Gleichheit (musāwāt) der Menschen und auf Freiheit (ḥurriyya) in dem, was das Gesetz nicht einschränkt. Diese dienen als Maßstäbe, um den Zweck der Urteile zu beurteilen."],
    ar: ["ما الخصائص العامة (لا المصالح المحددة) التي يعدّدها ابن عاشور في «مقاصد الشريعة الإسلامية» مقاصد أعم للشريعة؟", ["الفطرة والسماحة والمساواة والحرية", "الطاعة والصمت والكتمان والوحدة", "الصلاة والصيام والزكاة والحج", "العرض والمال والأسرة والتجارة"], "يتجاوز ابن عاشور (ت 1973م) الضروريات الخمس فيذكر السمات العامة للشريعة: موافقتها للفطرة الإنسانية، وقيامها على السماحة والتيسير، وعلى المساواة بين الناس، وعلى الحرية فيما لم يقيّده الشرع، وتُستعمل معايير في تقدير مقصد الأحكام."] },

  { id: "xtf-027", s: "tafsir", g: 4, d: 6, t: ["maqasid", "maslaha-mursala"], tr: ["maliki", "comparative"], src: "al-Shāṭibī, al-Iʿtiṣām; al-Ghazālī, al-Mustaṣfā; Ibn Qudāma, Rawḍat al-Nāẓir",
    en: ["What is maṣlaḥa mursala, and which school is most associated with using it as a source?", ["An interest that no text confirms or cancels specifically, used as a source of rulings, most associated with the Mālikī school", "An interest that a text explicitly cancels, used by the Ḥanafī school", "A text of the Sunna transmitted by a single narrator, used by the Shāfiʿīs", "A ruling established by consensus, used by the Ḥanbalīs"], "Maṣlaḥa mursala (‘unrestricted interest’) is a benefit that the sharīʿa neither specifically endorses nor rejects. The Mālikīs are the school most associated with it, under conditions (consistency with the sharīʿa’s purposes, rationality, removal of hardship), and al-Shāṭibī defends it in al-Iʿtiṣām. Al-Ghazālī accepted it only when it is a necessity, general and certain."],
    de: ["Was ist maṣlaḥa mursala, und welche Schule ist am meisten mit ihrer Verwendung als Quelle verbunden?", ["Ein Interesse, das kein Text im Einzelnen bestätigt oder aufhebt, als Quelle von Urteilen verwendet, am meisten mit der malikitischen Schule verbunden", "Ein Interesse, das ein Text ausdrücklich aufhebt, von der hanafitischen Schule verwendet", "Ein Text der Sunna, von einem einzelnen Überlieferer überliefert, von den Schafiiten verwendet", "Ein durch Konsens festgelegtes Urteil, von den Hanbaliten verwendet"], "Maṣlaḥa mursala (‚uneingeschränktes Interesse‘) ist ein Nutzen, den die Scharia weder im Einzelnen billigt noch verwirft. Die Malikiten sind die Schule, die am meisten mit ihr verbunden ist, unter Bedingungen (Übereinstimmung mit den Zielen der Scharia, Vernünftigkeit, Beseitigung von Härte), und aš-Šāṭibī verteidigt sie in al-Iʿtiṣām. Al-Ġazālī akzeptierte sie nur, wenn sie eine Notwendigkeit, allgemein und sicher ist."],
    ar: ["ما المصلحة المرسلة وأي مذهب هو الأكثر ارتباطًا بالاحتجاج بها؟", ["مصلحة لم يشهد لها نص معيّن بالاعتبار ولا بالإلغاء وتُستعمل مصدرًا للأحكام، والمذهب المالكي أشهر القائلين بها", "مصلحة ألغاها نص صراحةً ويأخذ بها الحنفية", "نص من السنة رواه راوٍ واحد ويأخذ به الشافعية", "حكم ثابت بالإجماع ويأخذ به الحنابلة"], "المصلحة المرسلة منفعة لا تشهد الشريعة لها بالاعتبار المعين ولا بالإلغاء، والمالكية أشهر من يحتج بها بشروط (ملاءمة مقاصد الشرع ومعقوليتها ورفع الحرج)، ويدافع عنها الشاطبي في «الاعتصام»، ولم يقبلها الغزالي إلا إذا كانت ضرورية كلية قطعية."] },

  { id: "xtf-028", s: "tafsir", g: 4, d: 7, t: ["methodology", "ikhtilaf-tanawwu"], src: "Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr, faṣl on the disagreement of the Salaf in tafsīr",
    en: ["How does Ibn Taymiyya classify the disagreement of the early commentators in tafsīr?", ["Mostly as ikhtilāf tanawwuʿ (variety), where different expressions or examples refer to the same meaning, and less often as ikhtilāf tadādd (real contradiction)", "All disagreements are real contradictions", "There was no disagreement among the Salaf in tafsīr", "All disagreements are only about the readings"], "Ibn Taymiyya says that the disagreements of the Salaf in tafsīr are few compared to those in rulings, and most are of variety: one gives an example, another a definition or another aspect, as when they name different instances of one description. Real contradictions exist but are fewer. This distinction helps a commentator reconcile reports rather than reject them."],
    de: ["Wie ordnet Ibn Taimiyya die Meinungsverschiedenheit der frühen Kommentatoren im Tafsīr ein?", ["Meist als iḫtilāf tanawwuʿ (Vielfalt), bei dem verschiedene Ausdrücke oder Beispiele denselben Sinn meinen, und seltener als iḫtilāf taḍādd (wirklicher Widerspruch)", "Alle Meinungsverschiedenheiten sind wirkliche Widersprüche", "Es gab unter den Salaf keine Meinungsverschiedenheit im Tafsīr", "Alle Meinungsverschiedenheiten betreffen nur die Lesarten"], "Ibn Taimiyya sagt, die Meinungsverschiedenheiten der Salaf im Tafsīr seien im Vergleich zu denen bei Rechtsurteilen gering, und die meisten seien von der Art der Vielfalt: Einer nennt ein Beispiel, ein anderer eine Definition oder einen anderen Aspekt, etwa wenn sie verschiedene Fälle einer Beschreibung nennen. Echte Widersprüche gibt es, aber weniger. Diese Unterscheidung hilft dem Kommentator, Berichte zu vereinen statt zu verwerfen."],
    ar: ["كيف يصنّف ابن تيمية اختلاف المفسرين الأوائل في التفسير؟", ["غالبه اختلاف تنوع تتعدد فيه العبارات أو الأمثلة والمعنى واحد، وأقله اختلاف تضاد", "كل اختلاف تضاد حقيقي", "لم يكن بين السلف اختلاف في التفسير", "كل اختلاف في القراءات وحدها"], "يقول ابن تيمية إن اختلاف السلف في التفسير قليل بالنسبة إلى اختلافهم في الأحكام، وأكثره اختلاف تنوع: يذكر أحدهم مثالًا وآخر تعريفًا أو وجهًا آخر، كما يذكرون أفرادًا مختلفة لوصف واحد، وفيه تضاد حقيقي أقل. وهذا التمييز يعين المفسر على الجمع بين الأقوال بدل ردّها."] },

  { id: "xtf-029", s: "tafsir", g: 4, d: 7, t: ["methodology", "companions-tafsir"], tr: ["comparative"], src: "al-Ḥākim, al-Mustadrak; Ibn al-Ṣalāḥ, Muqaddima fī ʿUlūm al-Ḥadīth; al-Suyūṭī, Tadrīb al-Rāwī",
    en: ["What rule did al-Ḥākim state about the explanation of a Companion who witnessed the revelation, and how did later scholars limit it?", ["He said that such a tafsīr has the status of a report from the Prophet; Ibn al-Ṣalāḥ and others limited this to the occasions of revelation and matters not open to opinion", "That it is never accepted", "That it always has the status of a hadith in all matters including law", "That it is accepted only if repeated by ten Companions"], "Al-Ḥākim said that the commentary of a Companion who witnessed the revelation is considered a raised (marfūʿ) report. Ibn al-Ṣalāḥ restricted this to things that cannot be a matter of opinion, such as the occasion of revelation or the unseen. Other tafsīr from Companions is treated as a statement of a Companion, a proof for many but not on the same level as a statement of the Prophet."],
    de: ["Welche Regel stellte al-Ḥākim zur Erklärung eines Gefährten auf, der die Offenbarung miterlebte, und wie schränkten spätere Gelehrte sie ein?", ["Er sagte, ein solcher Tafsīr habe den Rang eines Berichts vom Propheten; Ibn aṣ-Ṣalāḥ und andere beschränkten dies auf die Offenbarungsanlässe und Dinge, die nicht der Meinung offenstehen", "Dass er nie angenommen wird", "Dass er immer den Rang eines Hadith in allen Dingen einschließlich des Rechts hat", "Dass er nur angenommen wird, wenn zehn Gefährten ihn wiederholen"], "Al-Ḥākim sagte, die Auslegung eines Gefährten, der die Offenbarung miterlebte, gelte als erhobener (marfūʿ) Bericht. Ibn aṣ-Ṣalāḥ beschränkte dies auf Dinge, die nicht Sache der Meinung sein können, wie den Offenbarungsanlass oder das Verborgene. Anderer Tafsīr von Gefährten wird als Aussage eines Gefährten behandelt, für viele ein Beleg, aber nicht auf der Stufe einer Aussage des Propheten."],
    ar: ["ما القاعدة التي ذكرها الحاكم في تفسير الصحابي الذي شهد الوحي، وكيف قيّدها المتأخرون؟", ["قال إن تفسيره في حكم المرفوع إلى النبي ﷺ، وقصره ابن الصلاح وغيره على أسباب النزول وما لا مجال للرأي فيه", "إنه لا يُقبل أبدًا", "إنه دائمًا في حكم الحديث في كل المسائل حتى الأحكام", "إنه لا يُقبل إلا إذا كرّره عشرة من الصحابة"], "قال الحاكم إن تفسير الصحابي الذي شهد الوحي في حكم المرفوع، وقيّده ابن الصلاح بما لا مجال للرأي فيه كسبب النزول والأمور الغيبية، وسائر ما يُروى عن الصحابة من التفسير في حكم قول الصحابي، وهو حجة عند كثيرين دون منزلة قول النبي ﷺ."] },

  { id: "xtf-030", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Suyūṭī, Tafsīr al-Jalālayn, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["Who wrote Tafsīr al-Jalālayn, and how was it composed?", ["Jalāl al-Dīn al-Maḥallī wrote the second half (from al-Kahf to the end) and the Fātiḥa, and Jalāl al-Dīn al-Suyūṭī completed the remainder from al-Baqara to al-Isrāʾ", "Jalāl al-Dīn al-Suyūṭī alone, in ten volumes", "Al-Ṭabarī and Ibn Kathīr jointly", "Two students of al-Rāzī"], "Al-Maḥallī (d. 864 AH) began the commentary from Sūrat al-Kahf to the end and then the Fātiḥa, but died before completing it; al-Suyūṭī (d. 911 AH) completed it from al-Baqara to al-Isrāʾ, following al-Maḥallī’s method and brevity. The result is a short, widely used commentary in a single volume, hence the name ‘of the two Jalāls’."],
    de: ["Wer schrieb Tafsīr al-Ǧalālain, und wie entstand er?", ["Ǧalāl ad-Dīn al-Maḥallī schrieb die zweite Hälfte (von al-Kahf bis zum Ende) und die Fātiḥa, und Ǧalāl ad-Dīn as-Suyūṭī vollendete den Rest von al-Baqara bis al-Isrāʾ", "Ǧalāl ad-Dīn as-Suyūṭī allein, in zehn Bänden", "Aṭ-Ṭabarī und Ibn Kaṯīr gemeinsam", "Zwei Schüler ar-Rāzīs"], "Al-Maḥallī (gest. 864 n. H.) begann den Kommentar mit Sure al-Kahf bis zum Ende und dann der Fātiḥa, starb aber vor der Vollendung; as-Suyūṭī (gest. 911 n. H.) vollendete ihn von al-Baqara bis al-Isrāʾ nach al-Maḥallīs Methode und Kürze. Das Ergebnis ist ein kurzer, viel benutzter Kommentar in einem Band, daher der Name ‚der beiden Ǧalāl‘."],
    ar: ["من ألّف «تفسير الجلالين» وكيف أُلّف؟", ["كتب جلال الدين المحلي النصف الثاني (من الكهف إلى آخر القرآن) والفاتحة، وأتمّ جلال الدين السيوطي الباقي من البقرة إلى الإسراء", "جلال الدين السيوطي وحده في عشرة مجلدات", "الطبري وابن كثير معًا", "اثنان من تلاميذ الرازي"], "بدأ المحلي (ت 864هـ) التفسير من الكهف إلى آخر القرآن ثم الفاتحة ومات قبل إتمامه، فأتمّه السيوطي (ت 911هـ) من البقرة إلى الإسراء متبعًا طريقته وإيجازه. فهو تفسير مختصر شائع في مجلد واحد، ومن هنا اسم الجلالين."] },

  { id: "xtf-031", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Suyūṭī, al-Durr al-Manthūr fī al-Tafsīr bi-l-Maʾthūr, introduction",
    en: ["What is the nature of al-Suyūṭī’s al-Durr al-Manthūr fī al-Tafsīr bi-l-Maʾthūr?", ["A collection of reports from the Prophet, Companions and Successors on each verse, which he gives without their chains", "A grammatical commentary in verse", "A short commentary for children", "A study of the occasions of revelation only"], "Al-Suyūṭī gathered reports on each verse from a large number of earlier hadith and tafsīr works, giving only the source and omitting the chains, which is why its reports need verification in the original books. His earlier Tarjumān al-Qurʾān contained chains, and the Durr is an abridgement of it."],
    de: ["Welcher Art ist as-Suyūṭīs ad-Durr al-Manṯūr fī t-Tafsīr bi-l-Maʾṯūr?", ["Eine Sammlung von Berichten vom Propheten, den Gefährten und Nachfolgern zu jedem Vers, die er ohne ihre Ketten gibt", "Ein grammatischer Kommentar in Versen", "Ein kurzer Kommentar für Kinder", "Eine Studie nur der Offenbarungsanlässe"], "As-Suyūṭī sammelte Berichte zu jedem Vers aus einer großen Zahl früherer Hadith- und Tafsīr-Werke und gab nur die Quelle an, ohne die Ketten, weshalb seine Berichte in den Originalbüchern überprüft werden müssen. Sein früheres Tarǧumān al-Qurʾān enthielt Ketten, und der Durr ist eine Kürzung davon."],
    ar: ["ما طبيعة كتاب «الدر المنثور في التفسير بالمأثور» للسيوطي؟", ["جمع للروايات عن النبي ﷺ والصحابة والتابعين في كل آية يوردها بلا أسانيد", "تفسير نحوي منظوم", "تفسير مختصر للأطفال", "دراسة لأسباب النزول وحدها"], "جمع السيوطي الروايات في كل آية من مصنفات حديثية وتفسيرية كثيرة سابقة مكتفيًا بذكر المصدر وحذف الأسانيد، ولذلك تحتاج رواياته إلى التحقق في الأصول. وكان كتابه السابق «ترجمان القرآن» مسندًا والدر مختصر له."] },

  { id: "xtf-032", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tabari-method"], src: "al-Ṭabarī, Jāmiʿ al-Bayān ʿan Taʾwīl Āy al-Qurʾān, introduction; Ibn Taymiyya, Muqaddima fī Uṣūl al-Tafsīr",
    en: ["How is the method of al-Ṭabarī’s Jāmiʿ al-Bayān characterised?", ["He reports the views of earlier authorities with chains, then weighs them and states his preference, using language, the readings and sometimes grammar", "He gives only his own opinion with no chains", "He quotes only the Prophet’s explanations", "He only lists the readings"], "Al-Ṭabarī (d. 310 AH) lists the earlier opinions on each verse with chains of transmission, then gives his own preference (tarjīḥ), with reasons from the Arabic language, the readings and the consensus of the interpreters. His commentary is the main source for the early tradition, and many later commentaries depend on it."],
    de: ["Wie wird die Methode von aṭ-Ṭabarīs Ǧāmiʿ al-Bayān charakterisiert?", ["Er berichtet die Ansichten früherer Autoritäten mit Ketten, wägt sie dann ab und nennt seine Präferenz, gestützt auf Sprache, Lesarten und mitunter Grammatik", "Er gibt nur seine eigene Meinung ohne Ketten", "Er zitiert nur die Erklärungen des Propheten", "Er führt nur die Lesarten auf"], "Aṭ-Ṭabarī (gest. 310 n. H.) führt die früheren Meinungen zu jedem Vers mit Überliefererketten auf und gibt dann seine eigene Bevorzugung (tarǧīḥ) mit Gründen aus der arabischen Sprache, den Lesarten und dem Konsens der Ausleger. Sein Kommentar ist die Hauptquelle für die frühe Tradition, und viele spätere Kommentare hängen von ihm ab."],
    ar: ["كيف يوصَف منهج «جامع البيان» للطبري؟", ["يروي أقوال المتقدمين بالأسانيد ثم يوازن بينها ويرجّح معتمدًا اللغة والقراءات وأحيانًا النحو", "يذكر رأيه وحده بلا أسانيد", "لا يورد إلا تفسير النبي ﷺ", "يقتصر على ذكر القراءات"], "يسرد الطبري (ت 310هـ) أقوال المتقدمين في كل آية بأسانيدها ثم يرجّح بحجج من اللغة العربية والقراءات وإجماع المفسرين، وتفسيره المصدر الأول للمأثور المبكر وتعتمد عليه تفاسير كثيرة بعده."] },

  { id: "xtf-033", s: "tafsir", g: 4, d: 6, t: ["classical-works", "andalusi-tafsir"], src: "Ibn ʿAṭiyya, al-Muḥarrar al-Wajīz fī Tafsīr al-Kitāb al-ʿAzīz, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["What is Ibn ʿAṭiyya’s al-Muḥarrar al-Wajīz known for?", ["An Andalusī Mālikī commentary that condenses the views of al-Ṭabarī and others, with attention to language and readings, and praised by Ibn Taymiyya for being closer to the Sunna than many", "A commentary only on legal verses", "A commentary in verse", "A Shīʿī commentary"], "Abū Muḥammad Ibn ʿAṭiyya (d. 541 AH) of Granada abridged and verified earlier opinions, particularly those of al-Ṭabarī, and added linguistic and rhetorical notes. His work is used by al-Qurṭubī and Abū Ḥayyān. Ibn Taymiyya praised it as free of the excess of some other commentaries."],
    de: ["Wofür ist Ibn ʿAṭiyyas al-Muḥarrar al-Waǧīz bekannt?", ["Ein andalusisch-malikitischer Kommentar, der die Ansichten aṭ-Ṭabarīs und anderer verdichtet, mit Aufmerksamkeit für Sprache und Lesarten, und von Ibn Taimiyya als der Sunna näher gelobt als viele andere", "Ein Kommentar nur zu den Rechtsversen", "Ein Kommentar in Versen", "Ein schiitischer Kommentar"], "Abū Muḥammad Ibn ʿAṭiyya (gest. 541 n. H.) aus Granada kürzte und prüfte frühere Meinungen, besonders die aṭ-Ṭabarīs, und fügte sprachliche und rhetorische Anmerkungen hinzu. Sein Werk wird von al-Qurṭubī und Abū Ḥayyān genutzt. Ibn Taimiyya lobte es als frei von der Übertreibung mancher anderer Kommentare."],
    ar: ["بماذا يشتهر «المحرر الوجيز» لابن عطية؟", ["تفسير أندلسي مالكي يختصر أقوال الطبري وغيره بعناية باللغة والقراءات، أثنى عليه ابن تيمية بأنه أقرب إلى السنة من كثير من التفاسير", "تفسير لآيات الأحكام وحدها", "تفسير منظوم", "تفسير شيعي"], "اختصر أبو محمد ابن عطية الغرناطي (ت 541هـ) الأقوال المتقدمة وحققها خاصة أقوال الطبري وأضاف فوائد لغوية وبلاغية، وينقل عنه القرطبي وأبو حيان، وأثنى عليه ابن تيمية لخلوه من إسراف بعض التفاسير."] },

  { id: "xtf-034", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Shawkānī, Fatḥ al-Qadīr al-Jāmiʿ bayna Fannay al-Riwāya wa-l-Dirāya min ʿIlm al-Tafsīr; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["Why is al-Shawkānī’s Fatḥ al-Qadīr described as ‘uniting the two arts of riwāya and dirāya’?", ["Because it combines reports (athar) with linguistic and rational analysis (dirāya) in explaining the verses", "Because it contains only hadith", "Because it contains only grammar", "Because it was written by two authors"], "Muḥammad al-Shawkānī (d. 1250 AH) of Yemen sets in his subtitle that the work joins the two methods: reports from the Prophet, Companions and Successors (riwāya), and analysis of language, grammar and meaning (dirāya). It is widely used, though some find its approach selective."],
    de: ["Warum wird aš-Šaukānīs Fatḥ al-Qadīr als ‚Vereinigung der beiden Künste Riwāya und Dirāya‘ beschrieben?", ["Weil es Berichte (aṯar) mit sprachlicher und rationaler Analyse (dirāya) bei der Erklärung der Verse verbindet", "Weil es nur Hadithe enthält", "Weil es nur Grammatik enthält", "Weil es von zwei Autoren geschrieben wurde"], "Muḥammad aš-Šaukānī (gest. 1250 n. H.) aus dem Jemen nennt im Untertitel, dass das Werk beide Methoden verbindet: Berichte vom Propheten, den Gefährten und Nachfolgern (riwāya) und Analyse von Sprache, Grammatik und Sinn (dirāya). Es wird viel genutzt, obwohl manche seinen Ansatz als selektiv empfinden."],
    ar: ["لماذا يوصف «فتح القدير» للشوكاني بأنه «الجامع بين فنّي الرواية والدراية»؟", ["لأنه يجمع بين الآثار المروية والتحليل اللغوي والعقلي في بيان الآيات", "لأنه لا يتضمن إلا الأحاديث", "لأنه لا يتضمن إلا النحو", "لأنه ألّفه مؤلفان"], "نص محمد الشوكاني (ت 1250هـ) اليمني في عنوان كتابه على جمعه بين الطريقتين: الروايات عن النبي ﷺ والصحابة والتابعين، وتحليل اللغة والنحو والمعنى، وهو واسع التداول وإن رآه بعضهم انتقائيًّا."] },

  { id: "xtf-035", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Alūsī, Rūḥ al-Maʿānī fī Tafsīr al-Qurʾān al-ʿAẓīm wa-l-Sabʿ al-Mathānī, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["What is al-Alūsī’s Rūḥ al-Maʿānī, and what characterises it?", ["A large 19th-century commentary from Baghdad that collects the views of the earlier commentaries, with language, readings, law and allusive (ishārī) remarks", "A short commentary in a single volume", "A commentary by a student of al-Ṭabarī", "A translation into Persian"], "Shihāb al-Dīn al-Alūsī (d. 1270 AH), a Baghdad scholar of the Ottoman period, compiled an encyclopaedic commentary drawing on al-Rāzī, Abū Ḥayyān, al-Bayḍāwī and many others, discussing readings, grammar, law and giving allusive interpretations, and sometimes challenging the opinions he cites."],
    de: ["Was ist al-Alūsīs Rūḥ al-Maʿānī, und was kennzeichnet es?", ["Ein großer Kommentar des 19. Jahrhunderts aus Bagdad, der die Ansichten der früheren Kommentare sammelt, mit Sprache, Lesarten, Recht und andeutenden (ishārī) Bemerkungen", "Ein kurzer Kommentar in einem Band", "Ein Kommentar eines Schülers aṭ-Ṭabarīs", "Eine Übersetzung ins Persische"], "Šihāb ad-Dīn al-Alūsī (gest. 1270 n. H.), ein Gelehrter Bagdads der osmanischen Zeit, stellte einen enzyklopädischen Kommentar zusammen, der sich auf ar-Rāzī, Abū Ḥayyān, al-Bayḍāwī und viele andere stützt, Lesarten, Grammatik und Recht erörtert, andeutende Auslegungen gibt und mitunter die zitierten Meinungen kritisiert."],
    ar: ["ما «روح المعاني» للألوسي وما الذي يميزه؟", ["تفسير كبير من القرن التاسع عشر من بغداد يجمع آراء التفاسير السابقة مع اللغة والقراءات والفقه ولطائف إشارية", "تفسير مختصر في مجلد واحد", "تفسير لتلميذ الطبري", "ترجمة إلى الفارسية"], "ألّف شهاب الدين الألوسي (ت 1270هـ) عالم بغداد في العهد العثماني تفسيرًا موسوعيًّا استفاد من الرازي وأبي حيان والبيضاوي وغيرهم وبحث القراءات والنحو والفقه وأورد معاني إشارية، وناقش أحيانًا ما ينقله من أقوال."] },

  { id: "xtf-036", s: "tafsir", g: 4, d: 7, t: ["classical-works", "ibn-abbas-tafsir"], src: "al-Suyūṭī, al-Itqān, naw‘ 80 (ṭabaqāt al-mufassirīn); Ibn Ḥajar, Tahdhīb al-Tahdhīb; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["What is the scholarly view of the book Tanwīr al-Miqbās min Tafsīr Ibn ʿAbbās that circulates under the name of Ibn ʿAbbās?", ["It is a compilation attributed to him through a weak chain (al-Kalbī from Abū Ṣāliḥ), so its attribution is not reliable", "It is a book written by Ibn ʿAbbās himself, with a perfect chain", "It is the commentary of al-Ṭabarī under another name", "It was written in the 20th century"], "The compilation Tanwīr al-Miqbās, assembled by al-Fīrūzābādī, is based on a chain from Muḥammad ibn al-Sāʾib al-Kalbī, from Abū Ṣāliḥ, from Ibn ʿAbbās. The hadith critics considered al-Kalbī weak, so the transmission is not reliable. A sounder source from Ibn ʿAbbās is the Ṣaḥīfa of ʿAlī ibn Abī Ṭalḥa, which Aḥmad is reported to have praised."],
    de: ["Wie lautet das gelehrte Urteil über das Buch Tanwīr al-Miqbās min Tafsīr Ibn ʿAbbās, das unter dem Namen Ibn ʿAbbās’ kursiert?", ["Es ist eine Kompilation, die ihm über eine schwache Kette (al-Kalbī von Abū Ṣāliḥ) zugeschrieben wird, daher ist die Zuschreibung nicht verlässlich", "Es ist ein Buch, das Ibn ʿAbbās selbst schrieb, mit vollkommener Kette", "Es ist der Kommentar aṭ-Ṭabarīs unter anderem Namen", "Es wurde im 20. Jahrhundert geschrieben"], "Die von al-Fīrūzābādī zusammengestellte Kompilation Tanwīr al-Miqbās beruht auf einer Kette von Muḥammad ibn as-Sāʾib al-Kalbī über Abū Ṣāliḥ von Ibn ʿAbbās. Die Hadithkritiker hielten al-Kalbī für schwach, daher ist die Überlieferung nicht verlässlich. Eine gesündere Quelle von Ibn ʿAbbās ist die Ṣaḥīfa des ʿAlī ibn Abī Ṭalḥa, die Aḥmad gelobt haben soll."],
    ar: ["ما رأي العلماء في كتاب «تنوير المقباس من تفسير ابن عباس» المتداول باسم ابن عباس؟", ["هو جمع منسوب إليه بسند ضعيف (الكلبي عن أبي صالح) فلا تصح نسبته", "هو كتاب كتبه ابن عباس بنفسه بسند تام", "هو تفسير الطبري باسم آخر", "كُتب في القرن العشرين"], "الكتاب الذي جمعه الفيروزآبادي مبني على سند محمد بن السائب الكلبي عن أبي صالح عن ابن عباس، وقد ضعّف نقاد الحديث الكلبي فلا يوثق بنقله. ومن أقوى المصادر عن ابن عباس صحيفة علي بن أبي طلحة التي يُروى أن أحمد أثنى عليها."] },

  { id: "xtf-037", s: "tafsir", g: 4, d: 7, t: ["classical-works", "ibn-abbas-tafsir"], src: "al-Suyūṭī, al-Itqān, naw‘ 80; Ibn Ḥajar, Tahdhīb al-Tahdhīb, on ʿAlī ibn Abī Ṭalḥa",
    en: ["Which transmission of the tafsīr of Ibn ʿAbbās was praised by Aḥmad ibn Ḥanbal and used by al-Bukhārī and al-Ṭabarī?", ["The Ṣaḥīfa of ʿAlī ibn Abī Ṭalḥa from Ibn ʿAbbās", "The chain of al-Kalbī from Abū Ṣāliḥ", "The compilation of al-Fīrūzābādī", "The book of Muqātil ibn Sulaymān"], "ʿAlī ibn Abī Ṭalḥa (d. 143 AH) narrated tafsīr from Ibn ʿAbbās, though he did not meet him directly but through intermediaries; Aḥmad is quoted as saying that if a man travelled to Egypt for this ṣaḥīfa, it would not be a waste. Al-Bukhārī cites it in places and al-Ṭabarī relies on it. The transmission is regarded as a good, though not flawless, source."],
    de: ["Welche Überlieferung des Tafsīr von Ibn ʿAbbās wurde von Aḥmad ibn Ḥanbal gelobt und von al-Buḫārī und aṭ-Ṭabarī benutzt?", ["Die Ṣaḥīfa des ʿAlī ibn Abī Ṭalḥa von Ibn ʿAbbās", "Die Kette von al-Kalbī von Abū Ṣāliḥ", "Die Kompilation von al-Fīrūzābādī", "Das Buch des Muqātil ibn Sulaimān"], "ʿAlī ibn Abī Ṭalḥa (gest. 143 n. H.) überlieferte Tafsīr von Ibn ʿAbbās, ohne ihn selbst gesehen zu haben, sondern über Mittelsmänner; von Aḥmad wird zitiert, wenn ein Mann für diese Ṣaḥīfa nach Ägypten reiste, wäre das keine Verschwendung. Al-Buḫārī zitiert sie an einzelnen Stellen, und aṭ-Ṭabarī stützt sich auf sie. Die Überlieferung gilt als gute, wenn auch nicht makellose Quelle."],
    ar: ["أي رواية لتفسير ابن عباس أثنى عليها أحمد بن حنبل واعتمد عليها البخاري والطبري؟", ["صحيفة علي بن أبي طلحة عن ابن عباس", "سند الكلبي عن أبي صالح", "جمع الفيروزآبادي", "كتاب مقاتل بن سليمان"], "روى علي بن أبي طلحة (ت 143هـ) التفسير عن ابن عباس بواسطة لا بلقاء مباشر، ويُنقل عن أحمد قوله لو رحل رجل إلى مصر في هذه الصحيفة ما كان كثيرًا. وقد علّق البخاري عنها في مواضع واعتمد عليها الطبري، وهي مصدر جيد وإن لم يخل من كلام."] },

  { id: "xtf-038", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "Ibn Kathīr, Tafsīr al-Qurʾān al-ʿAẓīm, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["How is Ibn Kathīr’s Tafsīr al-Qurʾān al-ʿAẓīm generally characterised?", ["As a commentary bi-l-maʾthūr that explains the Quran first by the Quran, then by the Sunna and the early authorities, relying heavily on al-Ṭabarī and Ibn Abī Ḥātim and criticising weak reports", "As a commentary on legal verses only", "As a purely grammatical commentary", "As a mystical allusive commentary"], "Ibn Kathīr (d. 774 AH) follows the order he describes in his introduction, which is that of Ibn Taymiyya, and adds assessments of the chains of the reports and of the isrāʾīliyyāt. He does not include much grammar or theology. Its concision and use of the reports made it one of the most widely read commentaries."],
    de: ["Wie wird Ibn Kaṯīrs Tafsīr al-Qurʾān al-ʿAẓīm im Allgemeinen charakterisiert?", ["Als Kommentar bi-l-maʾṯūr, der den Koran zuerst durch den Koran, dann durch die Sunna und die frühen Autoritäten erklärt, sich stark auf aṭ-Ṭabarī und Ibn Abī Ḥātim stützt und schwache Berichte kritisiert", "Als Kommentar nur zu den Rechtsversen", "Als rein grammatischer Kommentar", "Als mystisch-andeutender Kommentar"], "Ibn Kaṯīr (gest. 774 n. H.) folgt der in seiner Einleitung beschriebenen Ordnung, die die Ibn Taimiyyas ist, und fügt Beurteilungen der Ketten der Berichte und der Isrāʾīliyyāt hinzu. Er bringt wenig Grammatik oder Theologie. Seine Kürze und der Gebrauch der Berichte machten ihn zu einem der meistgelesenen Kommentare."],
    ar: ["كيف يوصَف «تفسير القرآن العظيم» لابن كثير عمومًا؟", ["تفسير بالمأثور يفسر القرآن أولًا بالقرآن ثم بالسنة وأقوال السلف ويعتمد على الطبري وابن أبي حاتم كثيرًا وينتقد الأخبار الضعيفة", "تفسير لآيات الأحكام وحدها", "تفسير نحوي محض", "تفسير صوفي إشاري"], "سار ابن كثير (ت 774هـ) على الترتيب الذي ذكره في مقدمته وهو ترتيب ابن تيمية، وأضاف تقويم أسانيد الروايات والإسرائيليات، ولم يتوسع في النحو والكلام، فصار من أكثر التفاسير قراءة لإيجازه واستعماله الروايات."] },

  { id: "xtf-039", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], src: "al-Bayḍāwī, Anwār al-Tanzīl wa-Asrār al-Taʾwīl, introduction; Ḥājjī Khalīfa, Kashf al-Ẓunūn",
    en: ["What is the relation of al-Bayḍāwī’s Anwār al-Tanzīl to earlier commentaries?", ["It is a concise commentary that draws mainly on al-Zamakhsharī’s al-Kashshāf (leaving out its Muʿtazilī points) and on al-Rāzī, and became a standard text in the madrasas", "It is an expansion of al-Ṭabarī’s commentary", "It is a verse commentary on the Alfiyya", "It is a translation of Ibn Kathīr"], "Al-Bayḍāwī (d. around 685 AH) abridged al-Kashshāf, removing the Muʿtazilī doctrines and adding material from al-Rāzī, al-Rāghib and others, with an emphasis on language and meaning. It was widely taught in the Ottoman and Eastern lands and was the subject of many glosses (ḥawāshī)."],
    de: ["In welchem Verhältnis steht al-Bayḍāwīs Anwār at-Tanzīl zu früheren Kommentaren?", ["Es ist ein knapper Kommentar, der sich vor allem auf az-Zamaḫšarīs al-Kaššāf (unter Auslassung seiner muʿtazilitischen Punkte) und auf ar-Rāzī stützt und zu einem Standardtext der Madrasen wurde", "Es ist eine Erweiterung des Kommentars von aṭ-Ṭabarī", "Es ist ein Versekommentar zur Alfiyya", "Es ist eine Übersetzung von Ibn Kaṯīr"], "Al-Bayḍāwī (gest. um 685 n. H.) kürzte al-Kaššāf, entfernte die muʿtazilitischen Lehren und fügte Material von ar-Rāzī, ar-Rāġib und anderen hinzu, mit dem Schwerpunkt auf Sprache und Sinn. Er wurde in den osmanischen und östlichen Ländern viel gelehrt und war Gegenstand vieler Glossen (ḥawāšī)."],
    ar: ["ما علاقة «أنوار التنزيل» للبيضاوي بالتفاسير السابقة؟", ["تفسير موجز يعتمد أساسًا على «الكشاف» للزمخشري (مع حذف ما فيه من الاعتزال) وعلى الرازي وصار كتابًا معياريًّا في المدارس", "هو توسعة لتفسير الطبري", "هو شرح منظوم على الألفية", "هو ترجمة لابن كثير"], "اختصر البيضاوي (ت نحو 685هـ) الكشاف وحذف مسائل الاعتزال وأضاف من الرازي والراغب وغيرهما مع عناية باللغة والمعنى، فدُرّس كثيرًا في الشرق والبلاد العثمانية وكتب عليه الكثيرون حواشي."] },

  { id: "xtf-040", s: "tafsir", g: 4, d: 6, t: ["classical-works", "tafsir-authors"], tr: ["hanbali"], src: "Ibn al-Jawzī, Zād al-Masīr fī ʿIlm al-Tafsīr, introduction; al-Dhahabī, al-Tafsīr wa-l-Mufassirūn",
    en: ["How does Ibn al-Jawzī’s Zād al-Masīr fī ʿIlm al-Tafsīr present the verses?", ["Briefly, listing the different views on each point with their attribution to the early authorities", "As a single opinion with no mention of alternatives", "Only as a grammatical analysis", "Only through mystical allusions"], "Ibn al-Jawzī (d. 597 AH), a Ḥanbalī of Baghdad, compiled a medium-length commentary that, for each difficult point, lists the opinions with the names of those who held them, and is noted for ease of use. It is among the standard sources for locating attributions of tafsīr views."],
    de: ["Wie stellt Ibn al-Ǧauzīs Zād al-Masīr fī ʿIlm at-Tafsīr die Verse dar?", ["Knapp, indem es die verschiedenen Ansichten zu jedem Punkt mit ihrer Zuschreibung an die frühen Autoritäten aufführt", "Als eine einzige Meinung ohne Erwähnung von Alternativen", "Nur als grammatische Analyse", "Nur durch mystische Andeutungen"], "Ibn al-Ǧauzī (gest. 597 n. H.), ein Hanbalit aus Bagdad, stellte einen Kommentar mittlerer Länge zusammen, der zu jedem schwierigen Punkt die Meinungen mit den Namen derer aufführt, die sie vertraten, und für seine einfache Benutzbarkeit bekannt ist. Er gehört zu den Standardquellen, um die Zuschreibungen von Tafsīr-Ansichten aufzufinden."],
    ar: ["كيف يعرض «زاد المسير في علم التفسير» لابن الجوزي الآيات؟", ["بإيجاز مع ذكر الأقوال المختلفة في كل مسألة منسوبة إلى السلف", "برأي واحد دون ذكر الأقوال الأخرى", "تحليلًا نحويًّا فقط", "إشارات صوفية فقط"], "ألّف ابن الجوزي (ت 597هـ) الحنبلي البغدادي تفسيرًا متوسطًا يذكر في كل موضع مشكل الأقوال بأسماء قائليها، ويمتاز بسهولة الانتفاع به، وهو من المصادر المعتمدة لمعرفة نسبة الأقوال التفسيرية."] },
];
